GuiItem::processNonFocus(const GuiEvent& event)
	{
		for (size_t i = 0; i < numChildren(); i++)
		{
			GuiItem* current = getGuiItem((int)i);

			if (current && current != focus.get())
			{
				GuiResponse itemResponse = current->process(event);
				if (itemResponse.wasUsed())
				{
					this->loseFocus();

					focus = shared_from(current);
					focus->loseFocus();

					return itemResponse;
				}
			}
		}

		return GuiResponse::notUsed();
	}

GuiItem::processNonFocus(const GuiEvent& event)
	{
	for (unsigned int i = 0; i < numChildren(); ++i) {
		Instance* child = (*getChildren())[i].get();
		GuiItem* item = dynamic_cast<GuiItem*>(child);

		if (item != NULL && item != focus.get()) {
			GuiResponse itemResponse = item->process(event);

			if (itemResponse.wasUsed()) {
				loseFocus();
				focus = shared_from(item);
				focus->loseFocus();

				return itemResponse;
			}
		}
	}

	return GuiResponse::notUsed();
}

