GuiItem::process(const GuiEvent& event)
	{
		if (event.isMouseEvent() && event.eventType == UIEvent::MOUSE_IDLE)
			return GuiResponse::notUsed();

		if (focus)
		{
			if (focus->canLoseFocus())
			{
				GuiResponse response = processNonFocus(event);
				if (response.wasUsed())
					return response;
			}

			GuiResponse focusResponse = focus->process(event);
			if (focusResponse.wasUsed())
				return focusResponse;

			loseFocus();
		}

		RBXASSERT(!focus);
		return processNonFocus(event);
	}

GuiItem::process(const GuiEvent& event)
	{
	if (event.isMouseEvent() && event.eventType == UIEvent::MOUSE_IDLE) {
		return GuiResponse::notUsed();
	}

	if (focus != NULL) {
		if (focus->canLoseFocus()) {
			GuiResponse nonFocus = processNonFocus(event);

			if (nonFocus.wasUsed()) {
				return nonFocus;
			}
		}

		GuiResponse focusResponse = focus->process(event);

		if (focusResponse.wasUsed()) {
			return focusResponse;
		}

		loseFocus();
	}

	return processNonFocus(event);
}

TopMenuBar::getSize() const
	{
		G3D::Vector2 size(0.0f, 0.0f);

		for (size_t i = 0; i < numChildren(); i++)
		{
			const GuiItem* current = getGuiItem((int)i);

			if (current)
			{
				G3D::Vector2 childSize = current->getSize();
				switch (layoutStyle)
				{
				case Layout::VERTICAL:
					size.x = G3D::max(size.x, childSize.x);
					size.y += childSize.y;
					break;
				case Layout::HORIZONTAL:
					size.x += childSize.x;
					size.y = G3D::max(size.y, childSize.y);
					break;
				}
			}
		}

		return size;
	}

TopMenuBar::getSize() const
	{
	G3D::Vector2 size(0, 0);

	for (unsigned int i = 0; i < numChildren(); ++i) {
		Instance* child = (*getChildren())[i].get();
		GuiItem* item = dynamic_cast<GuiItem*>(child);

		if (item != NULL) {
			G3D::Vector2 childSize = item->getSize();

			switch (layoutStyle) {
			case Layout::HORIZONTAL:
				size.x += childSize.x;
				size.y = std::max(size.y, childSize.y);
				break;
			case Layout::VERTICAL:
				size.x = std::max(size.x, childSize.x);
				size.y += childSize.y;
				break;
			}
		}
	}

	return size;
}

