TopMenuBar::process(const GuiEvent& event)
	{
		if (isVisible())
		{
			GuiResponse response = GuiItem::process(event);
			if (response.wasUsed())
			{
				return response;
			}

			if (backdropColor.a > 0.0f && event.isMouseEvent() && getMyRect().pointInRect(event.mousePosition))
			{
				return GuiResponse::used();
			}
		}

		return GuiResponse::notUsed();
	}

TopMenuBar::process(const GuiEvent& event)
	{
	if (isVisible()) {
		GuiResponse childResponse = GuiItem::process(event);

		if (childResponse.wasUsed()) {
			return childResponse;
		}

		if (backdropColor.a > 0 && event.isMouseEvent() && getMyRect().pointInRect(event.mousePosition)) {
			return GuiResponse::used();
		}
	}

	return GuiResponse::notUsed();
}

