Humanoid::onEvent(const RunService* source, Stepped event)
	{
		if (currentState.get())
		{
			if (getParent())
			{
				State* prevState = currentState.get();
				PVInstance* parent = static_cast<PVInstance*>(getParent());

				setState(prevState->onStep(event.step, *parent->getTopPVController()));
			}

			if (getTorsoPrimitive())
			{
				getTorsoPrimitive()->setCanSleep(currentState->canSleep());
			}
		}

		checkForJointDeath();

		if (walkTimer > 0)
		{
			walkTimer--;
			if (walkTimer == 0)
				walkMode = DIRECTION_MOVE;
		}
	}

Humanoid::onEvent(const RunService* source, Stepped event)
	{
	State* state = currentState.get();

	if (state != NULL && getParent() != NULL) {
		State* next = state->onStep(event.step, *static_cast<PVInstance*>(getParent())->getTopPVController());

		if (next != state) {
			currentState.reset(next);
		}
	}
}

