PropertyDescriptor::write(const DescribedBase* instance, bool ignoreWriteProtection) const
		{
			if (!ignoreWriteProtection)
			{
				if (isReadOnly())
					return NULL;

				if (!canStreamWrite())
					return NULL;
			}

			XmlElement* element = new XmlElement(type.tag);
			element->addAttribute(name_name, &this->name);

			writeValue(instance, element);
			return element;
		}

PropertyDescriptor::write(const DescribedBase* instance, bool ignoreWriteProtection) const
		{
	if (!ignoreWriteProtection) {
		if (isReadOnly()) {
			return NULL;
		}

		if (!canStreamWrite()) {
			return NULL;
		}
	}

	XmlElement* element = new XmlElement(type.tag);

	element->addAttribute<const RBX::Name*>(name_name, &name);

	writeValue(instance, element);

	return element;
}

SignalDescriptor::findSignalInstance(const SignalSource* source) const
		{
			if (!source)
				return NULL;

			if (!source->signals)
				return NULL;

			std::map<const SignalDescriptor*, boost::shared_ptr<SignalInstance>>::const_iterator iter = source->signals->find(this);
			if (iter == source->signals->end())
				return NULL;

			return iter->second.get();
		}

SignalDescriptor::findSignalInstance(const SignalSource* source) const
		{
	if (source == NULL) {
		return NULL;
	}

	if (source->signals.get() == NULL) {
		return NULL;
	}

	SignalSource::SignalMap::const_iterator it = source->signals->find(this);

	if (it == source->signals->end()) {
		return NULL;
	}

	return it->second.get();
}

SignalDescriptor::getSignalInstance(SignalSource& source) const
		{
			if (!source.signals)
			{
				source.signals.reset(new std::map<const SignalDescriptor*, boost::shared_ptr<SignalInstance>>);
			}
			else
			{
				std::map<const SignalDescriptor*, boost::shared_ptr<SignalInstance>>::iterator iter = source.signals->find(this);
				if (iter != source.signals->end())
					return iter->second;
			}

			boost::shared_ptr<SignalInstance> signalInstance(newSignalInstance(source));
			(*source.signals)[this] = signalInstance;

			if (signalCreatedHook)
				signalCreatedHook(&source);

			return signalInstance;
		}

SignalDescriptor::getSignalInstance(SignalSource& source) const
		{
	if (source.signals.get() == NULL) {
		source.signals.reset(new SignalSource::SignalMap());
	}

	SignalSource::SignalMap::iterator iter = source.signals->find(this);

	if (iter != source.signals->end()) {
		return iter->second;
	}

	boost::shared_ptr<SignalInstance> si(newSignalInstance(source));

	(*source.signals)[this] = si;

	if (signalCreatedHook != NULL) {
		signalCreatedHook(&source);
	}

	return si;
}

Color3Bridge::newColor3(lua_State* L)
{
    float color[3];
    int nargs = std::min(3, lua_gettop(L));

    for (int i = 0; i < nargs; i++)
        color[i] = lua_tonumber(L, i+1);

    for (int i = nargs; i < 3; i++)
        color[i] = 0;

    pushColor3(L, color);
    return 1;
}

Color3Bridge::newColor3(lua_State* L)
{
	float color[3];

	int count = std::min(3, lua_gettop(L));

	for (int i = 0; i < count; i++) {
		color[i] = lua_tofloat(L, i + 1);
	}

	for (int i = count; i < 3; i++) {
		color[i] = 0.0f;
	}

	pushNewObject(L, G3D::Color3(color[0], color[1], color[2]));
	return 1;
}

Vector3Bridge::on_add(lua_State* L)
{
