Vector3Bridge::on_mul(lua_State* L)
{
    G3D::Vector3 a;
    if (getValue(L, 1, a))
    {
        G3D::Vector3 b;
        if (getValue(L, 2, b))
        {
            pushVector3(L, a*b);
            return 1;
        }
        else
        {
            float x = lua_tonumber(L, 2);
            pushVector3(L, a*x);
            return 1;
        }
    }
    else
    {
        a = getObject(L, 2);
        float x = lua_tonumber(L, 1);
        pushVector3(L, a*x);
        return 1;
    }
}

Vector3Bridge::on_mul(lua_State* L)
{
	G3D::Vector3 vector;

	if (getValue(L, 1, vector)) {
		G3D::Vector3 other;

		if (getValue(L, 2, other)) {
			pushVector3(L, vector * other);
			return 1;
		}

		pushVector3(L, vector * lua_tofloat(L, 2));
		return 1;
	}

	vector = getObject(L, 2);

	pushVector3(L, vector * lua_tofloat(L, 1));
	return 1;
}

Vector3Bridge::on_div(lua_State* L)
{
    G3D::Vector3 a;
    if (getValue(L, 1, a))
    {
        G3D::Vector3 b;
        if (getValue(L, 2, b))
        {
            pushVector3(L, a/b);
            return 1;
        }
        else
        {
            float x = lua_tonumber(L, 2);
            pushVector3(L, a/x);
            return 1;
        }
    }
    else
    {
        a = getObject(L, 2);
        float x = lua_tonumber(L, 1);
        G3D::Vector3 xVec(x,x,x);
        pushVector3(L, xVec/a);
        return 1;
    }
}

Vector3Bridge::on_div(lua_State* L)
{
	G3D::Vector3 vector;

	if (getValue(L, 1, vector)) {
		G3D::Vector3 other;

		if (getValue(L, 2, other)) {
			pushVector3(L, vector / other);
			return 1;
		}

		pushVector3(L, vector / lua_tofloat(L, 2));
		return 1;
	}

	vector = getObject(L, 2);

	float scalar = lua_tofloat(L, 1);

	pushVector3(L, G3D::Vector3(scalar, scalar, scalar) / vector);
	return 1;
}

Vector3Bridge::on_unm(lua_State* L)
