Extents::areaXZ() const
	{
		G3D::Vector3 delta = this->high - this->low;
		return delta.x * delta.z;
	}

Extents::areaXZ() const
	{
	return (high.x - low.x) * (high.z - low.z);
}

Extents::getCorner(int i) const
	{
		RBXASSERT(i >= 0);
		RBXASSERT(i <= 7);

		return G3D::Vector3(
			this->low[0 + 3 * (i / 4)],
			this->low[1 + 3 * (i / 2 % 2)],
			this->low[2 + 3 * (i % 2)]
		);
	}

Extents::getCorner(int i) const
	{
	const Vector3* corners = &low;

	return Vector3(corners[i / 4].x, corners[i / 2 % 2].y, corners[i % 2].z);
}

Extents::faceCenter(NormalId faceId) const
	{
		G3D::Vector3 v = this->center();

		int i = faceId % 3;
		if (faceId < NORM_X_NEG)
		{
			v[i] = this->high[i];
		}
		else
		{
			v[i] = this->low[i];
		}

		return v;
	}

Extents::faceCenter(NormalId faceId) const
	{
	Vector3 answer = (high + low) * 0.5f;

	const int axis = faceId % 3;
	answer[axis] = faceId < 3 ? high[axis] : low[axis];

	return answer;
}

Extents::containedByFrustum(const G3D::GCamera::Frustum& frustum) const
	{
		if (frustum.faceArray.size() > 0)
		{
			for (int i = 0; i < frustum.faceArray.size(); i++)
			{
				const G3D::Plane* plane = &frustum.faceArray[i].plane;
				for (int j = 0; j < 8; j++)
				{
					G3D::Vector3 corner = getCorner(j);
					if (!plane->halfSpaceContains(corner))
					{
						return false;
					}
				}
			}
		}

		return true;
	}

Extents::containedByFrustum(const G3D::GCamera::Frustum& frustum) const
	{
	for (int i = 0; i < frustum.faceArray.size(); ++i) {
		const Plane& plane = frustum.faceArray[i].plane;

		for (int j = 0; j < 8; ++j) {
			const Vector3 corner = getCorner(j);

			if (!plane.halfSpaceContains(corner)) {
				return false;
			}
		}
	}

	return true;
}

Extents::overlapsOrTouches(const Extents& other) const
	{
		return
			!(this->low.x > other.high.x) &&
			!(this->low.y > other.high.y) &&
			!(this->low.z > other.high.z) &&
			!(this->high.y < other.low.y) &&
			!(this->high.x < other.low.x) &&
			!(this->high.z < other.low.z);
	}

Extents::overlapsOrTouches(const Extents& other) const
	{
	if (!(low.x > other.high.x) && !(low.y > other.high.y) && !(low.z > other.high.z) && !(high.y < other.low.y) &&
		!(high.x < other.low.x) && !(high.z < other.low.z)) {
		return true;
	}

	return false;
}

Extents::separatedByMoreThan(const Extents& other, float distance) const
	{
		RBXASSERT(distance > 0.0);

		G3D::Vector3 dv(distance, distance, distance);

		Extents thisExpanded(*this);
		thisExpanded.low -= dv;
		thisExpanded.high += dv;

		return !thisExpanded.overlapsOrTouches(other);
	}

Extents::separatedByMoreThan(const Extents& other, float distance) const
	{
	Extents thisExpanded(*this);
	thisExpanded.expand(distance);

	return !thisExpanded.overlapsOrTouches(other);
}

