Guid::generateGUID(std::string& result)
	{
		result = "RBX";

		GUID guid;
		CoCreateGuid(&guid);

		wchar_t wszGUID[64] = {0};
		StringFromGUID2(guid, wszGUID, 64);

		char ansiClsid[64];
		WideCharToMultiByte(NULL, NULL, wszGUID, 64, ansiClsid, 64, NULL, NULL);

		result += ansiClsid;
		result.erase(40, 1);
		result.erase(27, 1);
		result.erase(22, 1);
		result.erase(17, 1);
		result.erase(12, 1);
		result.erase(3, 1);
	}

Guid::generateGUID(std::string& result)
	{
	GUID guid;

	result = "RBX";

	CoCreateGuid(&guid);

	WCHAR wszGUID[64] = L"";
	char ansiClsid[64];

	StringFromGUID2(guid, wszGUID, 64);
	WideCharToMultiByte(CP_ACP, 0, wszGUID, 64, ansiClsid, 64, NULL, NULL);

	result += ansiClsid;

	result.erase(0x28, 1);
	result.erase(0x1b, 1);
	result.erase(0x16, 1);
	result.erase(0x11, 1);
	result.erase(0x0c, 1);
	result.erase(0x03, 1);
}

