Log::formatTime(double time)
	{
		char buffer[64];
		if (time == 0.0)
			sprintf(buffer, "0s");

		if (time < 0.0)
			sprintf(buffer, "%.3gs", time);
		else if (time >= 0.1)
			sprintf(buffer, "%.3gs", time);
		else
			sprintf(buffer, "%.3gms", time * 1000.0);

		return buffer;
	}

