Log::writeEntry(Severity severity, const char* message)
	{
		//current()->timeStamp(false);
		::timeStamp(currentStream(), false);

		switch (severity)
		{
		case Error:
			currentStream() << error;
		case Warning:
			currentStream() << warning;
		case Information:
			currentStream() << information;
		}

		currentStream() << message;
		stream << '\n';
		currentStream().flush();
	}

Log::writeEntry(Severity severity, const char* message)
	{
	std::ofstream* out = currentStream();

	SYSTEMTIME now;
	GetLocalTime(&now);

	char stamp[256];
	sprintf(stamp, "%02u:%02u.%03u ", now.wHour, now.wMinute, now.wMilliseconds);

	*out << stamp;
	out->flush();

	switch (severity) {
	case Error:
		*currentStream() << error;
	case Warning:
		*currentStream() << warning;
	case Information:
		*currentStream() << information;
	}

	*currentStream() << message;
	stream << '\n';
	currentStream()->flush();
}

