Quaternion::toRotationMatrix(G3D::Matrix3& rot) const
	{
		float fTx  = 2.0f * this->x;
		float fTy  = 2.0f * this->y;
		float fTz  = 2.0f * this->z;
		float fTxx = fTx * this->x;
		float fTxy = fTy * this->x;
		float fTxz = fTz * this->x;
		float fTwx = fTx * this->w;
		float fTwy = fTy * this->w;
		float fTwz = fTz * this->w;
		float fTyy = fTy * this->y;
		float fTyz = fTz * this->y;
		float fTzz = fTz * this->z;

		rot[0][0] = 1.0 - (fTyy + fTzz);
		rot[0][1] = fTxy - fTwz;
		rot[0][2] = fTxz + fTwy;
		rot[1][0] = fTxy + fTwz;
		rot[1][1] = 1.0 - (fTxx + fTzz);
		rot[1][2] = fTyz - fTwx;
		rot[2][0] = fTxz - fTwy;
		rot[2][1] = fTyz + fTwx;
		rot[2][2] = 1.0 - (fTxx + fTyy);
	}

Quaternion::toRotationMatrix(G3D::Matrix3& rot) const
	{
	float tx = x * 2.0f;
	float ty = y * 2.0f;
	float tz = z * 2.0f;

	float twx = x * tx;
	float txy = x * ty;
	float txz = x * tz;
	float twxw = w * tx;
	float twy = w * ty;
	float wz = w * tz;
	float tyy = y * ty;
	float yz = y * tz;
	float zz = z * tz;

	rot[0][0] = 1.0f - (zz + tyy);
	rot[0][1] = txy - wz;
	rot[0][2] = twy + txz;
	rot[1][0] = wz + txy;
	rot[1][1] = 1.0f - (zz + twx);
	rot[1][2] = yz - twxw;
	rot[2][0] = txz - twy;
	rot[2][1] = yz + twxw;
	rot[2][2] = 1.0f - (tyy + twx);
}

