		if (invalidRunViewCount == 0)
		{
			invalidRunViewCount = (int)views.size();
			if (invalidRunViewCount > 0)
			{
				for (std::map<IRunView*, bool>::iterator iter = views.begin(); iter != views.end(); iter++)
