			float primaryPartY = primaryPart->getExtentsWorld().max().y;
			answer = (getExtentsWorld().max().y - primaryPartY) + 6.0f;
		}

		return answer;
	}

ModelInstance::computeFlagHeight() const
	{
	float height = 6.0f;

	if (primaryPart != NULL) {
		float partTop = primaryPart->getExtentsWorld().max().y;

		height = getExtentsWorld().max().y - partTop + 6.0f;
	}

	return height;
}

ModelInstance::getPrimaryPartInternal() const
	{
		if (primaryPart)
		{
			RBXASSERT(primaryPart->isDescendentOf(this));
			return primaryPart;
		}
		else
		{
			float biggest = -1.0f;
			PartInstance* biggestPart = NULL;
			for (size_t i = 0; i < numChildren(); ++i)
			{
				const Instance* child = getChild(i);
				const PVInstance* pvChild = dynamic_cast<const PVInstance*>(child);
				if (pvChild)
				{
					const Primitive* primitive = pvChild->getBiggestPrimitive();
					if (primitive)
					{
						PartInstance* part = PartInstance::fromPrimitive(const_cast<Primitive*>(primitive));
						RBXASSERT(!part || part->isDescendentOf(this));

						float area = part->getExtentsWorld().areaXZ();
						if (area > biggest)
						{
							biggest = area;
							biggestPart = part;
						}
					}
				}
			}

			updatePrimaryPart(biggestPart);
			return biggestPart;
		}
	}

ModelInstance::getPrimaryPartInternal() const
	{
	if (primaryPart != NULL) {
		return primaryPart;
	}

	float bestArea = -1.0f;
	PartInstance* best = NULL;

	for (unsigned int i = 0; i < numChildren(); i++) {
		const PVInstance* pv = dynamic_cast<const PVInstance*>(getChild(i));

		if (pv != NULL) {
			const Primitive* primitive = pv->getBiggestPrimitive();

			if (primitive != NULL) {
				PartInstance* part = PartInstance::fromPrimitive(const_cast<Primitive*>(primitive));

				float area = part->getExtentsWorld().areaXZ();

				if (area > bestArea) {
					bestArea = area;
					best = part;
				}
			}
		}
	}

	updatePrimaryPart(best);

	return best;
}

