PartInstance::onAncestorChanged(const AncestorChanged& event)
	{
		Instance::onAncestorChanged(event);
		RBXASSERT(&primitive);

		World* world = Workspace::getWorldIfInWorkspace(this);
		if (world != myWorld)
		{
			RBXASSERT(myWorld || !primitive.getClump());

			if (myWorld)
			{
				setMovingManager(NULL);
				myWorld->removePrimitive(&primitive);
			}

			myWorld = world;

			if (world)
			{
				world->insertPrimitive(&primitive);
				setMovingManager(Workspace::getMyWorkspaceFast(this));
				primitive.setController(getTopPVController());
			}
		}
	}

PartInstance::onAncestorChanged(const AncestorChanged& event)
	{
	Instance::onAncestorChanged(event);

	World* world = Workspace::getWorldIfInWorkspace(this);

	if (world != myWorld) {
		if (myWorld != NULL) {
			setMovingManager(NULL);

			myWorld->removePrimitive(getPrimitive());
		}

		myWorld = world;

		if (world != NULL) {
			world->insertPrimitive(getPrimitive());

			setMovingManager(Workspace::getMyWorkspaceFast(this));

			getPrimitive()->setController(getTopPVController());
		}
	}
}

