		if (partType != Part::BLOCK_PART) {
			if (formFactor != SYMETRIC) {
				formFactor = SYMETRIC;

				raisePropertyChanged(prop_formFactor);
			}
		}

		raisePropertyChanged(prop_shapeXml);
		raisePropertyChanged(prop_shapeUi);

