Block::getMomentHollow(float mass) const
	{
		G3D::Vector3 grid = gridSize;
		G3D::Vector3 I;

		float area = ((grid.x * grid.z + grid.y * grid.z) + grid.x * grid.y) * 2;

		for (int i = 0; i < 3; i++)
		{
			float X = grid[(i    ) % 3];
			float Y = grid[(i + 1) % 3];
			float Z = grid[(i + 2) % 3];

			float scaling = mass / (2 * area);

			float temp = (Z*Z*Y)*X + (Y*Y*Y*Z)/3 + (Z*Z*Z*Y)/3 + (Y*Y*Z)*X + (X*Y*Y*Y)/3 + (X*Z*Z*Z)/3;

			I[i] = temp * scaling;
		}

		return Math::fromDiagonal(I);
	}

Block::getMomentHollow(float mass) const
	{
	float x = gridSize.x, y = gridSize.y, z = gridSize.z;

	float area = 2.0f * ((y + x) * z + y * x);

	Vector3 I(
		mass / (2 * area) *
			(z * z * y * x + z * y * y * y / 3 + z * z * z * x / 3 + z * y * y * x + y * y * y * x / 3 +
			 z * z * z * y / 3),
		mass / (2 * area) *
			(x * x * x * y / 3 + z * z * x * z / 3 + x * x * z * y + z * z * x * y + x * x * x * z / 3 +
			 z * z * z * y / 3),
		mass / (2 * area) *
			(y * y * y * z / 3 + y * x * x * z + y * x * x * x / 3 + y * y * z * x + x * x * x * z / 3 +
			 y * y * y * x / 3)
	);

	return Math::fromDiagonal(I);
}

