BallBallContact::computeIsColliding(float overlapIgnored)
	{
		float b0Radius = this->ball(0)->getRadius();
		float b1Radius = this->ball(1)->getRadius();

		G3D::Vector3 delta = this->getPrimitive(1)->getBody()->getPV().position.translation - this->getPrimitive(0)->getBody()->getPV().position.translation;
		float b0b1RadiusSum = b0Radius + b1Radius;

		if (b0b1RadiusSum > Math::longestVector3Component(delta))
			return delta.magnitude() < (b0b1RadiusSum - overlapIgnored);
		else
			return false;
	}

BallBallContact::computeIsColliding(float overlapIgnored)
	{
	float r0 = getPrimitive(0)->getGeometry()->getRadius();
	float r1 = getPrimitive(1)->getGeometry()->getRadius();

	const Vector3& p0 = getPrimitive(0)->getBody()->getPV().position.translation;
	const Vector3& p1 = getPrimitive(1)->getBody()->getPV().position.translation;

	float dx = p1.x - p0.x;
	float dy = p1.y - p0.y;
	float dz = p1.z - p0.z;

	float radiusSum = r0 + r1;

	if (radiusSum > std::max(fabsf(dx), std::max(fabsf(dy), fabsf(dz)))) {
		return sqrtf(dx * dx + dy * dy + dz * dz) < radiusSum - overlapIgnored;
	}

	return false;
}

BallBallContact::stepContact()
	{
		if (BallBallContact::computeIsColliding(0.0f))
		{
			if (this->inStage(IStage::KERNEL_STAGE))
			{
				if (!this->ballBallConnector)
					this->ballBallConnector = this->createConnector();

				this->ballBallConnector->setBallBall(
					this->getPrimitive(0)->getBody(), 
					this->getPrimitive(1)->getBody(), 
					this->ball(0)->getRadius(), 
					this->ball(1)->getRadius()
					);
			}
			return true;
		}
		else
		{
			this->deleteAllConnectors();
		}

		return false;
	}

BallBallContact::stepContact()
	{
	if (BallBallContact::computeIsColliding(0.0f)) {

		if (inKernel()) {

			if (ballBallConnector == NULL) {
				ballBallConnector = createConnector();
			}

			Ball* ball1 = ball(1);
			Ball* ball0 = ball(0);

			ContactConnector* connector = ballBallConnector;

			Body* body1 = getBody(1);
			Body* body0 = getBody(0);

			float radius0 = ball0->getRadius();
			float radius1 = ball1->getRadius();

			connector->setBallBall(body0, body1, radius0, radius0 + radius1);
		}

		return true;
	}

	deleteAllConnectors();

	return false;
}

BallBlockContact::stepContact()
	{
		G3D::Vector3int16 clip;
		G3D::Vector3 projectionInBlock;
		int onBoarder;

		if (BallBlockContact::computeIsColliding(onBoarder, clip, projectionInBlock, 0.0f))
		{
			if (this->inStage(IStage::KERNEL_STAGE))
			{
				if (!this->ballBlockConnector)
					this->ballBlockConnector = this->createConnector();

				const G3D::Vector3* offset;
				NormalId normId;
				GeoPairType ballInsideType;

				if (onBoarder)
					ballInsideType = this->block()->getBallBlockInfo(onBoarder, clip, offset, normId);
				else
					ballInsideType = this->block()->getBallInsideInfo(projectionInBlock, offset, normId);

				this->ballBlockConnector->setBallBlock(
					this->ballPrim()->getBody(),
					this->blockPrim()->getBody(),
					this->ball()->getRadius(),
					offset,
					normId,
					ballInsideType
					);
			}
			return true;
		}
		else
		{
			this->deleteAllConnectors();
		}

		return false;
	}

BallBlockContact::stepContact()
	{
	int onBorder;
	Vector3int16 clip;
	Vector3 projectionInBlock(0, 0, 0);

	if (computeIsColliding(onBorder, clip, projectionInBlock, 0.0f)) {

		if (inKernel()) {

			if (ballBlockConnector == NULL) {
				ballBlockConnector = createConnector();
			}

			const Vector3* offset;
			NormalId normalID;

			GeoPairType pairType = onBorder != 0 ? block()->getBallBlockInfo(onBorder, clip, offset, normalID)
												 : block()->getBallInsideInfo(projectionInBlock, offset, normalID);

			ballBlockConnector->setBallBlock(getBody(0), getBody(1), ball()->getRadius(), offset, normalID, pairType);
		}

		return true;
	}

	deleteAllConnectors();

	return false;
}

BlockBlockContact::deleteAllConnectors()
	{
		for (size_t i = 0; i < this->connectors.size(); i++)
		{
			this->deleteConnectorInline(this->connectors[i]);
		}

		this->connectors.resize(0, false);
		this->matched.resize(0, false);
	}

BlockBlockContact::deleteAllConnectors()
	{
	for (unsigned int i = 0; i < connectors.size(); i++) {
		deleteConnector(connectors[i]);
	}

	connectors.resize(0);
	matched.resize(0);
}

BlockBlockContact::deleteUnmatchedConnectors()
	{
		RBXASSERT(this->matched.size() == this->connectors.size());

		for (int i = (int)this->connectors.size()-1; i >= 0; i--)
		{
			bool match = this->matched[i];
			if (match == false)
			{
				ContactConnector* connector = this->connectors[i];
				this->connectors.fastRemove(i);
				this->matched.fastRemove(i);
				this->deleteConnectorInline(connector);
			}
		}
	}

BlockBlockContact::deleteUnmatchedConnectors()
	{
	for (int i = connectors.size() - 1; i >= 0; i--) {

		if (!matched[i]) {

			ContactConnector* c = connectors[i];

			fastRemoveIndex(connectors, i);
			fastRemoveIndex(matched, i);

			deleteConnector(c);
		}
	}
}

BlockBlockContact::matchContactConnector(Body* b0, Body* b1, GeoPairType _pairType, int param0, int param1)
	{
		RBXASSERT(this->matched.size() == this->connectors.size());

		for (size_t i = 0; i < this->matched.size(); i++)
		{
			if (this->matched[i] == false)
			{
				if (this->connectors[i]->match(b0, b1, _pairType, param0, param1))
				{
					this->matched[i] = true;
					Contact::contactPairMatches++;
					return this->connectors[i];
				}
			}
		}

		Contact::contactPairMisses++;
		ContactConnector* connector = this->createConnector();
		this->connectors.append(connector);
		this->matched.append(true);
		return connector;
	}

BlockBlockContact::matchContactConnector(Body* b0, Body* b1, GeoPairType _pairType, int param0, int param1)
	{
	for (unsigned int i = 0; i < matched.size(); i++) {

		if (!matched[i]) {

			if (connectors[i]->match(b0, b1, _pairType, param0, param1)) {

				matched[i] = true;

				contactPairMatches++;

				return connectors[i];
			}
		}
	}

	contactPairMisses++;

	ContactConnector* c = createConnector();

	connectors.push_back(c);
	matched.push_back(true);

	return c;
}

BlockBlockContact::loadGeoPairEdgeEdge(int b0, int b1, int edge0, int edge1)
	{
		NormalId edgeNormal0 = this->block(b0)->getEdgeNormal(edge0);
		NormalId edgeNormal1 = this->block(b1)->getEdgeNormal(edge1);

		ContactConnector* matched = this->matchContactConnector(
											this->getPrimitive(b0)->getBody(), 
											this->getPrimitive(b1)->getBody(), 
											EDGE_EDGE_PAIR, 
											edgeNormal0, 
											edgeNormal1
											);

		matched->setEdgeEdge(
			this->getPrimitive(b0)->getBody(), 
			this->getPrimitive(b1)->getBody(), 
			this->block(b0)->getEdgeVertex(edge0), 
			this->block(b1)->getEdgeVertex(edge1), 
			edgeNormal0, 
			edgeNormal1
			);
	}

BlockBlockContact::loadGeoPairEdgeEdge(int b0, int b1, int edge0, int edge1)
	{
	NormalId normalID0 = block(b0)->getEdgeNormal(edge0);
	NormalId normalID1 = block(b1)->getEdgeNormal(edge1);

	ContactConnector* c = matchContactConnector(getBody(b0), getBody(b1), EDGE_EDGE_PAIR, normalID0, normalID1);

	c->setEdgeEdge(
		getBody(b0),
		getBody(b1),
		block(b0)->getEdgeVertex(edge0),
		block(b1)->getEdgeVertex(edge1),
		normalID0,
		normalID1
	);
}

