BlockBlockContact::getBestPlaneEdge(bool& planeContact, float overlapIgnored)
	{
		float bestPlaneLength = Math::inf();
		float bestEdgeLength = Math::inf();
		float lastPlaneLength = Math::inf();
		int lastFeature[2] = {this->feature[0], this->feature[1]};
		bool checkLastFeature = (lastFeature[0] >= 0 && lastFeature[0] < 6) || (lastFeature[1] >= 0 && lastFeature[1] < 6);

		bool belowOverlap = false;

		for (int i = this->separatingBodyId; i < this->separatingBodyId + 2; i++)
		{
			int baseId = i % 2;
			int testId = (i + 1) % 2;

			const G3D::CoordinateFrame& primPV0 = this->getPrimitive(baseId)->getBody()->getPV().position;
			const G3D::CoordinateFrame& primPV1 = this->getPrimitive(testId)->getBody()->getPV().position;
			const G3D::Vector3* eBase = (const G3D::Vector3*)this->block(baseId)->getVertices();
			const G3D::Vector3* eTest = (const G3D::Vector3*)this->block(testId)->getVertices();

			G3D::Vector3 delta = primPV1.translation - primPV0.translation;

			G3D::Vector3 rotTransMul = delta * primPV0.rotation;

			for (int j = this->separatingAxisId; j < this->separatingAxisId + 3; j++)
			{
				int axisId = j % 3;

				float what = Math::taxiCabMagnitude(primPV0.rotation.getColumn(axisId) * primPV1.rotation * *eTest) + (*eBase)[axisId] - fabs(rotTransMul[axisId]);

				if (what > overlapIgnored)
				{
					if (checkLastFeature && lastFeature[baseId] % 3 == axisId )
						lastPlaneLength = what;

					if (what < bestPlaneLength)
					{
						bestPlaneLength = what;
						this->feature[baseId] = rotTransMul[axisId] > 0.0f ? axisId : axisId + 3;
						this->feature[testId] = -1;
						this->separatingBodyId = baseId;
						this->separatingAxisId = axisId;
						planeContact = true;
					}
				}
				else
				{
					this->separatingBodyId = baseId;
					this->separatingAxisId = axisId;
					belowOverlap = true;
				}

				if (belowOverlap)
					return false;
			}
		}

		if (checkLastFeature) 
		{
			if (this->feature[0] != lastFeature[0] || this->feature[1] != lastFeature[1]) 
			{
				if (!(bestPlaneLength * 1.01f < lastPlaneLength))
				{
					bestPlaneLength = lastPlaneLength;
					this->feature[0] = lastFeature[0];
					this->feature[1] = lastFeature[1];
				}
			}
		}
		const G3D::CoordinateFrame& primPV0 = this->getPrimitive(0)->getBody()->getPV().position;
		const G3D::CoordinateFrame& primPV1 = this->getPrimitive(1)->getBody()->getPV().position;
		const G3D::Vector3* e0 = (const G3D::Vector3*)this->block(0)->getVertices();
		const G3D::Vector3* e1 = (const G3D::Vector3*)this->block(1)->getVertices();

		G3D::Vector3 p0p1 = primPV1.translation - primPV0.translation;

		for (int i = 0; i < 3; i++)
		{
			for (int j = 0; j < 3; j++)
			{
				G3D::Vector3 crossAxis = primPV0.rotation.getColumn(i).cross(primPV1.rotation.getColumn(j));
				if (crossAxis.unitize() <= 0.001f)
					return planeContact;

				float p0p1inCrossAxis = crossAxis.dot(p0p1);

				G3D::Vector3 crossAxisMulPV0rot = crossAxis * primPV0.rotation;
				G3D::Vector3 crossAxisMulPV1rot = crossAxis * primPV1.rotation;

				float what = Math::taxiCabMagnitude(crossAxisMulPV0rot * *e0) + Math::taxiCabMagnitude(crossAxisMulPV1rot * *e1) - fabs(p0p1inCrossAxis);
				if (what > overlapIgnored)
				{
					if (what < bestEdgeLength)
					{
						bestEdgeLength = what;

						if ( what * 10.0 < bestPlaneLength )
						{
							if ( p0p1inCrossAxis > 0.0 )
							{
								this->feature[0] = this->block(0)->getClosestEdge(primPV0.rotation, (NormalId)i, crossAxis) + 6;
								this->feature[1] = this->block(1)->getClosestEdge(primPV1.rotation, (NormalId)j, -crossAxis) + 6;
							}
							else
							{
								this->feature[0] = this->block(0)->getClosestEdge(primPV0.rotation, (NormalId)i, -crossAxis) + 6;
								this->feature[1] = this->block(1)->getClosestEdge(primPV1.rotation, (NormalId)j, crossAxis) + 6;
							}
							planeContact = false;
						}
					}
				}
				else
				{
					 return false;
				}
			}
		}
		return true;
	}

BlockBlockContact::getBestPlaneEdge(bool& planeContact, float overlapIgnored)
	{
	float bestPlaneLength = Math::inf();
	float bestEdgeLength = Math::inf();
	float lastPlaneLength = Math::inf();

	int lastFeature[2] = {feature[0], feature[1]};

	bool checkLastFeature = (lastFeature[0] >= 0 && lastFeature[0] < 6) || (lastFeature[1] >= 0 && lastFeature[1] < 6);

	for (int i = separatingBodyId; i < separatingBodyId + 2; i++) {

		int baseId = i % 2;
		int i1 = (i + 1) % 2;

		const CoordinateFrame& cBase = getBody(baseId)->getCoordinateFrame();
		const CoordinateFrame& cTest = getBody(i1)->getCoordinateFrame();

		const Vector3& eBase = block(baseId)->getExtent();
		const Vector3& eTest = block(i1)->getExtent();

		Vector3 pTestInBase = cBase.pointToObjectSpace(cTest.translation);

		for (int testId = separatingAxisId; testId < separatingAxisId + 3; testId++) {

			int j = testId % 3;

			Vector3 eBaseInTest = cBase.rotation.getColumn(j) * cTest.rotation;

			float length = fabsf(eBaseInTest.y * eTest.y) + fabsf(eBaseInTest.x * eTest.x) +
						   fabsf(eBaseInTest.z * eTest.z) + eBase[j] - fabsf(pTestInBase[j]);

			if (!(length > overlapIgnored)) {
				separatingBodyId = baseId;
				separatingAxisId = j;

				return false;
			}

			if (checkLastFeature) {
				if (lastFeature[baseId] % 3 == j) {
					lastPlaneLength = length;
				}
			}

			if (length < bestPlaneLength) {
				bestPlaneLength = length;

				feature[baseId] = pTestInBase[j] > 0 ? j : j + 3;
				feature[i1] = -1;

				separatingBodyId = baseId;
				separatingAxisId = j;

				planeContact = true;
			}
		}
	}

	if (checkLastFeature && (feature[0] != lastFeature[0] || feature[1] != lastFeature[1]) &&
		!(bestPlaneLength * 1.01f < lastPlaneLength)) {

		bestPlaneLength = lastPlaneLength;

		feature[0] = lastFeature[0];
		feature[1] = lastFeature[1];
	}

	const CoordinateFrame& c0 = getBody(0)->getCoordinateFrame();
	const CoordinateFrame& c1 = getBody(1)->getCoordinateFrame();

	const Vector3& extent0 = block(0)->getExtent();
	const Vector3& extent1 = block(1)->getExtent();

	Vector3 p0p1 = c1.translation - c0.translation;

	for (int i = 0; i < 3; i++) {
		for (int j = 0; j < 3; j++) {

			Vector3 crossAxis = c0.rotation.getColumn(i).cross(c1.rotation.getColumn(j));

			if (crossAxis.unitize() <= 0.001f) {
				return planeContact;
			}

			float p0p1inCrossAxis = p0p1.dot(crossAxis);

			Vector3 crossInBase = crossAxis * c0.rotation;
			Vector3 crossInTest = crossAxis * c1.rotation;

			float length = fabsf(crossInBase.x * extent0.x) + fabsf(crossInBase.y * extent0.y) +
						   fabsf(crossInBase.z * extent0.z) + fabsf(crossInTest.x * extent1.x) +
						   fabsf(crossInTest.y * extent1.y) + fabsf(crossInTest.z * extent1.z) - fabsf(p0p1inCrossAxis);

			if (!(length > overlapIgnored)) {
				return false;
			}

			if (length < bestEdgeLength) {
				bestEdgeLength = length;

				if (length * 10.0f < bestPlaneLength) {

					if (p0p1inCrossAxis > 0) {
						feature[0] = block(0)->getClosestEdge(c0.rotation, (NormalId) i, crossAxis) + 6;
						feature[1] = block(1)->getClosestEdge(c1.rotation, (NormalId) j, -crossAxis) + 6;
					}
					else {
						Vector3 negCrossAxis = -crossAxis;

						feature[0] = block(0)->getClosestEdge(c0.rotation, (NormalId) i, negCrossAxis) + 6;
						feature[1] = block(1)->getClosestEdge(c1.rotation, (NormalId) j, crossAxis) + 6;
					}

					planeContact = false;
				}
			}
		}
	}

	return true;
}

BlockBlockContact::stepContact()
	{
		bool planeContact;
		if (computeIsColliding(planeContact, 0.0f))
		{
			if (inStage(IStage::KERNEL_STAGE))
			{
				matched.resize(connectors.size(), false);
				for (int i = 0; i < connectors.size(); ++i)
					matched[i] = false;
				if (planeContact)
				{
					computePlaneContact();
					deleteUnmatchedConnectors();
					return true;
				}
				loadGeoPairEdgeEdge(0, 1, feature[0] - 6, feature[1] - 6);
				deleteUnmatchedConnectors();
			}
			return true;
		}
		else
		{
			deleteAllConnectors();
			feature[0] = -1;
			feature[1] = -1;
			return false;
		}
	}

BlockBlockContact::stepContact()
	{
	bool planeContact;

	if (Primitive::aaBoxCollide(*getPrimitive(0), *getPrimitive(1)) && getBestPlaneEdge(planeContact, 0.0f)) {

		if (inKernel()) {

			matched.resize(0);
			matched.resize(connectors.size());

			if (planeContact) {
				computePlaneContact();
			}
			else {
				loadGeoPairEdgeEdge(0, 1, feature[0] - 6, feature[1] - 6);
			}

			deleteUnmatchedConnectors();
		}

		return true;
	}

	deleteAllConnectors();

	feature[0] = -1;
	feature[1] = -1;

	return false;
}

BlockBlockContact::computePlaneContact()
	{
		if (feature[0] >= 0)
		{
			planeID = (NormalId)feature[0];
			bPlane = 0;
			bOther = 1;
		}
		else
		{
			planeID = (NormalId)feature[1];
			bPlane = 1;
			bOther = 0;
		}

		const G3D::CoordinateFrame& otherFrame = getPrimitive(bOther)->getBody()->getPV().position;
		const G3D::CoordinateFrame& planeFrame = getPrimitive(bPlane)->getBody()->getPV().position;

		G3D::CoordinateFrame otherToPlane = planeFrame.inverse() * otherFrame;

		Block* otherBlock = block(bOther);
		Block* planeBlock = block(bPlane);

		G3D::Vector3 otherVertexPlaneCoords = Math::getWorldNormal(planeID, planeFrame);
		otherPlaneID = Math::getClosestObjectNormalId(-otherVertexPlaneCoords, otherFrame.rotation);

		G3D::Vector2 planeRect = planeBlock->getProjectedVertex(*(planeBlock->getFaceVertex(planeID, 0)),planeID);

		G3D::Vector2 otherQuad[4] = {};

		for (int i = 0; i < 4; i++)
		{
			G3D::Vector3 world = otherToPlane.pointToWorldSpace(*(otherBlock->getFaceVertex(otherPlaneID, i)));
			otherQuad[i] = otherBlock->getProjectedVertex(world, planeID);
		}
		return intersectRectQuad(planeRect, otherQuad);
	}

BlockBlockContact::computePlaneContact()
	{
	if (feature[0] >= 0) {
		planeID = (NormalId) feature[0];
		bPlane = 0;
		bOther = 1;
	}
	else {
		planeID = (NormalId) feature[1];
		bPlane = 1;
		bOther = 0;
	}

	const CoordinateFrame& otherCoord = getBody(bOther)->getCoordinateFrame();
	const CoordinateFrame& planeCoord = getBody(bPlane)->getCoordinateFrame();

	CoordinateFrame otherToPlane = planeCoord.inverse() * otherCoord;

	Block& otherBlock = *block(bOther);
	Block& planeBlock = *block(bPlane);

	int planeFlip = planeID / 3;
	int planeAxis = planeID - 3 * planeFlip;

	otherPlaneID = Math::getClosestObjectNormalId(
		-(Vector3(
			  planeCoord.rotation[0][planeAxis],
			  planeCoord.rotation[1][planeAxis],
			  planeCoord.rotation[2][planeAxis]
		  ) *
		  (float) (1 - 2 * planeFlip)),
		otherCoord.rotation
	);

	Vector2 planeRect = planeBlock.getProjectedVertex(*planeBlock.getFaceVertex(planeID, 0), planeID);

	Vector2 otherQuad[4];

	for (int i = 0; i < 4; i++) {
		const Vector3& otherVertex = *otherBlock.getFaceVertex(otherPlaneID, i);

		Vector3 otherVertexPlaneCoords = otherToPlane.pointToWorldSpace(otherVertex);

		otherQuad[i] = otherBlock.getProjectedVertex(otherVertexPlaneCoords, planeID);
	}

	return intersectRectQuad(planeRect, otherQuad);
}

