IMovingManager::onMovingHeartbeat()
	{
		RBXASSERT(current == moving.end());

		current = moving.begin();
		while (current != moving.end())
		{
			IMoving* iMoving = *current;

			if (iMoving->checkSleep())
				remove(iMoving);
			else
				current++;
		}
	}

IMovingManager::onMovingHeartbeat()
	{
	for (current = moving.begin(); current != moving.end();) {
		IMoving* m = *current;

		if (m->checkSleep()) {
			remove(m);
		}
		else {
			++current;
		}
	}
}

