Joint::canBuildJoint(Primitive* p0, Primitive* p1, NormalId nId0, NormalId nId1, float angleMax, float planarMax)
	{
		if (!Math::fuzzyAxisAligned(p0->getCoordinateFrame().rotation, p1->getCoordinateFrame().rotation, angleMax))
			return false;

		Face f0 = p0->getFaceInWorld(nId0);
		Face f1 = p1->getFaceInWorld(nId1);
		if (!Face::hasOverlap(f0, f1, 0.35f))
			return false;

		if (!Face::overlapWithinPlanes(f0, f1, planarMax))
			return false;

		return true;
	}

Joint::canBuildJoint(Primitive* p0, Primitive* p1, NormalId nId0, NormalId nId1, float angleMax, float planarMax)
	{
	if (!Math::fuzzyAxisAligned(p0->getCoordinateFrame().rotation, p1->getCoordinateFrame().rotation, angleMax)) {
		return false;
	}

	Face f0 = p0->getFaceInWorld(nId0);
	Face f1 = p1->getFaceInWorld(nId1);

	if (!Face::hasOverlap(f0, f1, 0.35f)) {
		return false;
	}

	return Face::overlapWithinPlanes(f0, f1, planarMax) ? true : false;
}

JointBuilder::canJoin(Primitive* p0, Primitive* p1)
	{
		const Extents& fuzzyExtent1 = p0->getFastFuzzyExtents();
		const Extents& fuzzyExtent2 = p1->getFastFuzzyExtents();

		if (fuzzyExtent1.separatedByMoreThan(fuzzyExtent2, 0.05f))
		{
			return NULL;
		}

		const G3D::CoordinateFrame& c0 = p0->getCoordinateFrame();
		const G3D::CoordinateFrame& c1 = p1->getCoordinateFrame();

		for (int i = 0; i < 6; i++)
		{	
			int tempI = i % 3;
			G3D::Vector3 c0Rotation;
			c0Rotation.x = c0.rotation[0][tempI];
			c0Rotation.y = c0.rotation[1][tempI];
			c0Rotation.z = c0.rotation[2][tempI];
			c0Rotation *= ((i / 3) * -2 + 1);

			NormalId id2 = Math::getClosestObjectNormalId(-c0Rotation, c1.rotation);
			Joint* joint = RotateJoint::canBuildJoint(p0, p1, (NormalId)i, id2);

			if (joint)
				return joint;

			joint = WeldJoint::canBuildJoint(p0, p1, (NormalId)i, id2);

			if (joint)
				return joint;

			joint = SnapJoint::canBuildJoint(p0, p1, (NormalId)i, id2);

			if (joint)
				return joint;

			joint = GlueJoint::canBuildJoint(p0, p1, (NormalId)i, id2);

			if (joint)
				return joint;
		}
		return NULL;
	}

JointBuilder::canJoin(Primitive* p0, Primitive* p1)
	{
	const Extents& r0 = p0->getFastFuzzyExtents();
	const Extents& r1 = p1->getFastFuzzyExtents();

	if (r0.separatedByMoreThan(r1, 0.05f)) {
		return NULL;
	}

	const CoordinateFrame& coord0 = p0->getCoordinateFrame();
	const CoordinateFrame& coord1 = p1->getCoordinateFrame();

	for (int i = 0; i < 6; ++i) {
		NormalId normalId0 = (NormalId) i;
		Vector3 normal = -Math::getWorldNormal(normalId0, coord0);
		NormalId normalId1 = Math::getClosestObjectNormalId(normal, coord1.rotation);

		if (Joint* joint = RotateJoint::canBuildJoint(p0, p1, normalId0, normalId1)) {
			return joint;
		}

		if (Joint* joint = WeldJoint::canBuildJoint(p0, p1, normalId0, normalId1)) {
			return joint;
		}

		if (Joint* joint = SnapJoint::canBuildJoint(p0, p1, normalId0, normalId1)) {
			return joint;
		}

		if (Joint* joint = GlueJoint::canBuildJoint(p0, p1, normalId0, normalId1)) {
			return joint;
		}
	}

	return NULL;
}

