JointStage::removeFromMap(Joint* j, Primitive* p)
	{
		typedef std::multimap<Primitive*, Joint*>::iterator Iterator;

		if (!p)
			return;

		RBXASSERT(pairInMap(j, p));

		for (Iterator it = jointMap.lower_bound(p); it != jointMap.upper_bound(p); it++)
		{
			if (it->second == j) 
			{
				jointMap.erase(it);
				RBXASSERT(!pairInMap(j, p));
				return;
			}
		}

		RBXASSERT(0);
	}

JointStage::removeFromMap(Joint* j, Primitive* p)
	{
	do {
		if (p == NULL) {
			break;
		}

		JointMap::iterator pos;

		for (pos = jointMap.lower_bound(p); pos != jointMap.upper_bound(p); ++pos) {
			if (pos->second == j) {
				jointMap.erase(pos);
				return;
			}
		}
	} while (0);
}

