		if (edgeHasPrimitivesDownstream(j))
		{
			RBXASSERT(!pairInMap(j, p));
			RBXASSERT(pairInMap(j, j->otherPrimitive(p)));

			removeFromList(j);
			removeFromMap(j, j->otherPrimitive(p));
			moveJointToDownstream(j);
		}
		else
		{
			insertToMap(j, p);
		}
	}

