MotorJoint::isAligned()
	{
		G3D::CoordinateFrame baseWorld = getPrimitive(0)->getCoordinateFrame() * jointCoord0;
		G3D::CoordinateFrame otherBaseWorld = getPrimitive(1)->getCoordinateFrame() * jointCoord1;

		if (Math::fuzzyEq(baseWorld.translation, otherBaseWorld.translation, 0.00001f))
		{
			if (Math::fuzzyEq(baseWorld.rotation.getColumn(2), otherBaseWorld.rotation.getColumn(2), 0.00001f))
				return true;
		}

		return false;
	}

MotorJoint::isAligned()
	{
	CoordinateFrame baseWorld = getPrimitive(0)->getCoordinateFrame() * jointCoord0;
	CoordinateFrame rotorWorld = getPrimitive(1)->getCoordinateFrame() * jointCoord1;

	return Math::fuzzyEq(baseWorld.translation, rotorWorld.translation, 1.0e-5f) &&
		   Math::fuzzyEq(baseWorld.rotation.getColumn(2), rotorWorld.rotation.getColumn(2), 1.0e-5f);
}

MotorJoint::stepUi(int uiStepId)
	{
		if (fabs(desiredAngle - currentAngle) < fabs(maxVelocity))
		{
			setCurrentAngle(desiredAngle);
		}
		else
		{
			if (fabs(maxVelocity) > 0.0f)
				setCurrentAngle(currentAngle + fabs(maxVelocity));
			else
				setCurrentAngle(currentAngle - fabs(maxVelocity));
		}
	}

MotorJoint::stepUi(int uiStepId)
	{
	float maxStep = fabs(maxVelocity);

	float delta = desiredAngle - currentAngle;

	if (fabs(delta) < maxStep) {
		setCurrentAngle(desiredAngle);
	}
	else if (delta > 0.0f) {
		setCurrentAngle(currentAngle + maxStep);
	}
	else {
		setCurrentAngle(currentAngle - maxStep);
	}
}

