	{
	Clump* clump0 = p0->clump;
	Clump* clump1 = p1->clump;

	if (p0->myOwner->reportTouches()) {
		if (clump0->getSleepStatus() == Sim::AWAKE || clump1->getSleepStatus() == Sim::AWAKE) {
			p0->world->onPrimitiveTouched(p0, p1);
