	clump0 = p1->clump;
	clump1 = p0->clump;

	if (p1->myOwner->reportTouches()) {
		if (clump0->getSleepStatus() == Sim::AWAKE || clump1->getSleepStatus() == Sim::AWAKE) {
			p1->world->onPrimitiveTouched(p1, p0);
		}
	}
}

