		{
			bool oldDrag = !dragging && canCollide;
			dragging = _dragging;

			setAnchor(anchored);
			if (world)
			{
				bool newDrag = !dragging && canCollide;
				if (newDrag != oldDrag)
					world->onPrimitiveCanCollideChanged(this);
			}
		}
	}

Primitive::setDragging(bool _dragging)
	{
	if (dragging != _dragging) {
		bool wasCollideable = !dragging && canCollide;

		dragging = _dragging;
		setAnchor(anchored);

		if (world != NULL) {
			bool isCollideable = !dragging && canCollide;

			if (isCollideable != wasCollideable) {
				world->onPrimitiveCanCollideChanged(this);
			}
		}
	}
}

Primitive::setAnchor(bool _anchored)
	{
		anchored = _anchored;

		bool exists = getAnchor();

		if (_anchored || dragging)
			_anchored = true;

		if (_anchored == exists)
			return;

		if (_anchored)
		{
			RBXASSERT(!getAnchorObject());
			setAnchorObject(new Anchor(this));
			if (world)
				world->onPrimitiveAddedAnchor(this);
		}
		else
		{
			RBXASSERT(getAnchorObject());
			if (world)
				world->onPrimitiveRemovingAnchor(this);

			delete getAnchorObject();
			setAnchorObject(NULL);
		}
	}

Primitive::setAnchor(bool _anchored)
	{
	bool have = anchorObject != NULL;

	anchored = _anchored;

	bool wanted = _anchored || dragging;

	if (wanted != have) {
		if (wanted) {
			anchorObject = new Anchor(this);

			if (world != NULL) {
				world->onPrimitiveAddedAnchor(this);
			}
		}
		else {
			delete anchorObject;
			anchorObject = NULL;

			if (world != NULL) {
				world->onPrimitiveRemovedAnchor(this);
			}
		}
	}
}

