Primitive::getNextEdge(Edge* e) const
	{
		if (Joint::isJoint(e))
		{
			Edge* next = joints.next(e);
			return next ? next : contacts.first();
		}
		return contacts.next(e);
	}

Primitive::getNextEdge(Edge* e) const
	{
	Edge* next = e->getNext(this);

	if (next != NULL) {
		return next;
	}

	if (e->getEdgeType() == Edge::JOINT) {
		return contacts.first;
	}

	return NULL;
}

Primitive::getJoint(Primitive* p0, Primitive* p1)
	{
		Primitive* least = p0->getNumJoints2() < p1->getNumJoints2() ? p0 : p1;

		for (Joint* current = least->getFirstJoint(); current != NULL; current = least->getNextJoint(current))
		{
			if (p0 == current->getPrimitive(0) && p1 == current->getPrimitive(1) || p0 == current->getPrimitive(1) && p1 == current->getPrimitive(0))
			   return current;
		}
		return NULL;
	}

Primitive::getJoint(Primitive* p0, Primitive* p1)
	{
	Primitive* shortest = p0->joints.num < p1->joints.num ? p0 : p1;

	for (Joint* joint = shortest->getFirstJoint(); joint != NULL; joint = shortest->getNextJoint(joint)) {
		if ((p0 == joint->getPrimitive(0) && p1 == joint->getPrimitive(1)) ||
			(p0 == joint->getPrimitive(1) && p1 == joint->getPrimitive(0))) {
			return joint;
		}
	}

	return NULL;
}

Primitive::getContact(Primitive* p0, Primitive* p1)
	{
		Primitive* least = p0->getNumContacts() < p1->getNumContacts() ? p0 : p1;

		for (Contact* current = least->getFirstContact(); current != NULL; current = least->getNextContact(current))
		{
			if (p0 == current->getPrimitive(0) && p1 == current->getPrimitive(1) || p0 == current->getPrimitive(1) && p1 == current->getPrimitive(0))
			   return current;
		}
		return NULL;
	}

Primitive::getContact(Primitive* p0, Primitive* p1)
	{
	Primitive* shortest = p0->contacts.num < p1->contacts.num ? p0 : p1;

	for (Contact* contact = shortest->getFirstContact(); contact != NULL; contact = shortest->getNextContact(contact)) {
		if ((p0 == contact->getPrimitive(0) && p1 == contact->getPrimitive(1)) ||
			(p0 == contact->getPrimitive(1) && p1 == contact->getPrimitive(0))) {
			return contact;
		}
	}

	return NULL;
}

Primitive::getFirstRigidAt(Edge* start)
	{
		for (Edge* current = start; current != NULL; current = getNextEdge(current))
		{
			if (RigidJoint::isRigidJoint(current))
				return rbx_static_cast<RigidJoint*>(current);
		}
		return NULL;
	}

Primitive::getFirstRigidAt(Edge* start)
	{
	while (start != NULL) {
		if (RigidJoint::isRigidJoint(start)) {
			return static_cast<RigidJoint*>(start);
		}

		start = getNextEdge(start);
	}

	return NULL;
}

Primitive::insertEdge(Edge* e)
	{
		Primitive* p0 = e->getPrimitive(0);
		Primitive* p1 = e->getPrimitive(1);

		if (Joint::isJoint(e))
		{
			e->getPrimitive(0)->joints.insertEdge(e);

			if (p1)
				e->getPrimitive(1)->joints.insertEdge(e);
			else
				RBXASSERT(rbx_static_cast<Joint*>(e)->getJointType() == Joint::ANCHOR_JOINT || rbx_static_cast<Joint*>(e)->getJointType() == Joint::FREE_JOINT);
		}
		else
		{
			e->getPrimitive(0)->contacts.insertEdge(e);
			e->getPrimitive(1)->contacts.insertEdge(e);
		}
	}

Primitive::insertEdge(Edge* e)
	{
	Primitive* prim0 = e->getPrimitive(0);
	Primitive* prim1 = e->getPrimitive(1);

	if (e->getEdgeType() == Edge::JOINT) {
		EdgeList::insertEdge(prim0, e, e->getPrimitive(0)->joints);

		if (prim1 != NULL) {
			EdgeList::insertEdge(prim1, e, e->getPrimitive(1)->joints);
		}
	}
	else {
		EdgeList::insertEdge(prim0, e, e->getPrimitive(0)->contacts);
		EdgeList::insertEdge(prim1, e, e->getPrimitive(1)->contacts);
	}
}

Primitive::removeEdge(Edge* e)
	{
		Primitive* p0 = e->getPrimitive(0);
		Primitive* p1 = e->getPrimitive(1);

		if (Joint::isJoint(e))
		{
			e->getPrimitive(0)->joints.removeEdge(e);

			if (p1)
				e->getPrimitive(1)->joints.removeEdge(e);
			else
				RBXASSERT(rbx_static_cast<Joint*>(e)->getJointType() == Joint::ANCHOR_JOINT || rbx_static_cast<Joint*>(e)->getJointType() == Joint::FREE_JOINT);
		}
		else
		{
			e->getPrimitive(0)->contacts.removeEdge(e);
			e->getPrimitive(1)->contacts.removeEdge(e);
		}
	}

Primitive::removeEdge(Edge* e)
	{
	Primitive* prim0 = e->getPrimitive(0);
	Primitive* prim1 = e->getPrimitive(1);

	if (e->getEdgeType() == Edge::JOINT) {
		EdgeList::removeEdge(prim0, e, e->getPrimitive(0)->joints);

		if (prim1 != NULL) {
			EdgeList::removeEdge(prim1, e, e->getPrimitive(1)->joints);
		}
	}
	else {
		EdgeList::removeEdge(prim0, e, e->getPrimitive(0)->contacts);
		EdgeList::removeEdge(prim1, e, e->getPrimitive(1)->contacts);
	}
}

RigidJoint::isAligned()
	{
		G3D::CoordinateFrame c0World = getPrimitive(0)->getCoordinateFrame() * jointCoord0;
		G3D::CoordinateFrame c1World = getPrimitive(1)->getCoordinateFrame() * jointCoord1;
		return Math::fuzzyEq(c0World, c1World, 0.00001f, 0.00001f);
	}

RigidJoint::isAligned()
	{
	Primitive* prim0 = getPrimitive(0);
	CoordinateFrame c0World = prim0->getCoordinateFrame() * jointCoord0;

	Primitive* prim1 = getPrimitive(1);
	CoordinateFrame c1World = prim1->getCoordinateFrame() * jointCoord1;

	return Math::fuzzyEq(c0World, c1World, 1e-5f, 1e-5f);
}

RigidJoint::align(Primitive* pMove, Primitive* pStay)
	{
		const G3D::CoordinateFrame& c0 = getJointCoord(pMove == getPrimitive(0) ? 0 : 1);
		const G3D::CoordinateFrame& c1 = getJointCoord(pStay == getPrimitive(0) ? 0 : 1);

		G3D::CoordinateFrame jointWorld = pStay->getCoordinateFrame() * c1;
		return jointWorld * c0.inverse();
	}

RigidJoint::align(Primitive* pMove, Primitive* pStay)
	{
	CoordinateFrame& coord0 = pMove == getPrimitive(0) ? jointCoord0 : jointCoord1;
	CoordinateFrame& coord1 = pStay == getPrimitive(0) ? jointCoord0 : jointCoord1;

	CoordinateFrame jointWorld = pStay->getCoordinateFrame() * coord1;

	return jointWorld * coord0.inverse();
}

RigidJoint::getChildInParent(Primitive* parent, Primitive* child)
	{
		const G3D::CoordinateFrame& c0 = getJointCoord(parent == getPrimitive(0) ? 0 : 1);
		const G3D::CoordinateFrame& c1 = getJointCoord(child == getPrimitive(0) ? 0 : 1);

		return c0 * c1.inverse();
	}

RigidJoint::getChildInParent(Primitive* parent, Primitive* child)
	{
	CoordinateFrame& parentCoord = parent == getPrimitive(0) ? jointCoord0 : jointCoord1;
	CoordinateFrame& childCoord = child == getPrimitive(0) ? jointCoord0 : jointCoord1;

	return parentCoord * childCoord.inverse();
}

