RotateJoint::getChannelValue(int uiStepId)
	{
		RBXASSERT(getAxlePrim());
		const SurfaceData& axleSurface = getAxlePrim()->getSurfaceData(getAxleId());

		Controller* controller = getAxlePrim()->getController();
		RBXASSERT(controller);

		float value = controller->getValue(axleSurface.inputType);
		float paramA = axleSurface.paramA;
		float paramB = axleSurface.paramB;

		float dt = Constants::uiDt() * uiStepId;

		switch (axleSurface.inputType)
		{
		case Controller::NO_INPUT:
			return 0.0;
		case Controller::CONSTANT_INPUT:
			return paramB;
		case Controller::SIN_INPUT:
			return sin(dt * paramB) * paramA;
		case Controller::LEFT_TRACK_INPUT:
			if (value < -0.1)
				return value * fabs(paramA);
			else if (value > 0.1)
				return value * fabs(paramB);
			return 0.0;
		case Controller::RIGHT_TRACK_INPUT:
			if (value < -0.1)
				return -(value * fabs(paramA));
			else if (value > 0.1)
				return -(value * fabs(paramB));
			return 0.0;
		default:
			if (value < -0.1)
				return -(value * paramA);
			else if (value > 0.1)
				return value * paramB;
			return 0.0;
		}
	}

RotateJoint::getChannelValue(int uiStepId)
	{
	const SurfaceData& surfaceData = getAxlePrim()->getSurfaceData(getAxleId());

	float controllerValue = getAxlePrim()->getController()->getValue(surfaceData.inputType);
	float paramA = surfaceData.paramA;
	float paramB = surfaceData.paramB;
	float time = Constants::uiDt() * uiStepId;

	switch (surfaceData.inputType) {
	case Controller::CONSTANT_INPUT:
		return paramB;
	case Controller::SIN_INPUT:
		return sin(time * paramB) * paramA;
	case Controller::NO_INPUT:
		break;
	case Controller::LEFT_TRACK_INPUT:
		if (controllerValue < -0.1) {
			return fabs(paramA) * controllerValue;
		}
		if (0.1 < controllerValue) {
			return fabs(paramB) * controllerValue;
		}
		break;
	case Controller::RIGHT_TRACK_INPUT:
		if (controllerValue < -0.1) {
			return -(fabs(paramA) * controllerValue);
		}
		if (0.1 < controllerValue) {
			return -(fabs(paramB) * controllerValue);
		}
		break;
	default:
		if (controllerValue < -0.1) {
			return -(controllerValue * paramA);
		}
		if (0.1 < controllerValue) {
			return controllerValue * paramB;
		}
		break;
	}

	return 0.0f;
}

RotateJoint::canBuildJoint(Primitive* p0, Primitive* p1, NormalId nId0, NormalId nId1)
	{
		SurfaceType s0 = p0->getSurfaceType(nId0);
		SurfaceType s1 = p1->getSurfaceType(nId1);
		if (!(s0 >= ROTATE || s1 >= ROTATE))
			return NULL;

		const G3D::CoordinateFrame& c0 = p0->getCoordinateFrame();
		const G3D::CoordinateFrame& c1 = p1->getCoordinateFrame();

		G3D::Vector3 n0 = Math::getWorldNormal(nId0, c0);
		G3D::Vector3 n1 = Math::getWorldNormal(nId1, c1);

		G3D::Vector3 holePtWorld = -n1;
		if (Math::angle(n0, holePtWorld) > 0.025f)
			return NULL;

		Face f0 = p0->getFaceInWorld(nId0);
		Face f1 = p1->getFaceInWorld(nId1);

		if (Face::hasOverlap(f0, f1, 0.35f) && Face::overlapWithinPlanes(f0, f1, 0.05f))
		{
			G3D::Vector3 center0 = f0.center();
			G3D::Vector3 center1 = f1.center();

			bool inExtrusion0 = f0.fuzzyContainsInExtrusion(center0, 0.05f);
			bool inExtrusion1 = f1.fuzzyContainsInExtrusion(center1, 0.05f);
			bool cond0 = s0 >= ROTATE && inExtrusion0;
			bool cond1 = s1 >= ROTATE && inExtrusion1;

			if (!cond0 && !cond1)
				return NULL;

			if (!cond0 || (cond1 && p0->getGridSize().sum() > p1->getGridSize().sum()))
			{
				std::swap(nId0, nId1);
				std::swap(s0, s1);
				std::swap(center0, center1);
				std::swap(n0, n1);
				std::swap(p0, p1);
			}

			G3D::CoordinateFrame axleInP0 = p0->getFaceCoordInObject(nId0);
			G3D::Vector3 axlePtWorld = p0->getCoordinateFrame().pointToWorldSpace(axleInP0.translation);
			G3D::Vector3 axlePtInP1 = p1->getCoordinateFrame().pointToObjectSpace(axlePtWorld);

			NormalId oppNId1 = normalIdOpposite(nId1);
			G3D::Vector3 byAtLeast = Math::toGrid(axlePtInP1, 0.1f);

			G3D::CoordinateFrame holeInP1(normalIdToMatrix3(oppNId1), byAtLeast);
			G3D::Vector3 holePtWorld = p1->getCoordinateFrame().pointToWorldSpace(holeInP1.translation);
			if (!Tolerance::pointsUnaligned(axlePtWorld, holePtWorld))
			{
				for (int i = 0; i < 2; i++)
				{
					float multiplier = i == 0 ? 1.0f : -1.0f;

					G3D::Vector3 ref0 = axlePtWorld - n0 * multiplier;
					G3D::Vector3 ref1 = holePtWorld + n1 * multiplier;
					if (Tolerance::pointsUnaligned(ref0, ref1))
						return NULL;
				}

				return surfaceTypeToJoint(s0, p0, p1, axleInP0, holeInP1);
			}
		}

		return NULL;
	}

RotateJoint::canBuildJoint(Primitive* p0, Primitive* p1, NormalId nId0, NormalId nId1)
	{
	SurfaceType surfaceType0 = p0->getSurfaceType(nId0);
	SurfaceType surfaceType1 = p1->getSurfaceType(nId1);

	if (surfaceType0 < ROTATE && surfaceType1 < ROTATE) {
		return NULL;
	}

	const CoordinateFrame& coord0 = p0->getCoordinateFrame();
	const CoordinateFrame& coord1 = p1->getCoordinateFrame();

	Vector3 n0 = Math::getWorldNormal(nId0, coord0);
	Vector3 n1 = Math::getWorldNormal(nId1, coord1);

	if (0.025f < Math::angle(n0, -n1)) {
		return NULL;
	}

	Face f0 = p0->getFaceInWorld(nId0);
	Face f1 = p1->getFaceInWorld(nId1);

	if (!Face::hasOverlap(f0, f1, 0.35f)) {
		return NULL;
	}

	if (!Face::overlapWithinPlanes(f0, f1, 0.05f)) {
		return NULL;
	}

	Vector3 center0 = f0.center();
	Vector3 center1 = f1.center();

	bool touchCenter0 = f1.fuzzyContainsInExtrusion(center0, 0.05f);
	bool contains1 = f0.fuzzyContainsInExtrusion(center1, 0.05f);

	bool axle0 = surfaceType0 >= ROTATE && touchCenter0;
	bool axle1 = surfaceType1 >= ROTATE && contains1;

	if (!axle0 && !axle1) {
		return NULL;
	}

	if (!axle0 || (axle1 && p1->getGeometry()->getGridSize().sum() > p0->getGeometry()->getGridSize().sum())) {
		surfaceType0 = surfaceType1;
		std::swap(p0, p1);
		std::swap(nId0, nId1);
		std::swap(center0, center1);
		std::swap(n0, n1);
	}

	CoordinateFrame axleInP0 = p0->getFaceCoordInObject(nId0);

	Vector3 axlePtWorld = p0->getCoordinateFrame().pointToWorldSpace(axleInP0.translation);
	Vector3 axlePtInP1 = p1->getCoordinateFrame().pointToObjectSpace(axlePtWorld);

	NormalId oppositeId = normalIdOpposite(nId1);

	CoordinateFrame holeInP1(normalIdToMatrix3(oppositeId), Math::toGrid(axlePtInP1, 0.1f));

	Vector3 holePtWorld = p1->getCoordinateFrame().pointToWorldSpace(holeInP1.translation);

	if (Tolerance::pointsUnaligned(axlePtWorld, holePtWorld)) {
		return NULL;
	}

	for (int i = 0; i < 2; ++i) {
		float offset = i == 0 ? 1.0f : -1.0f;
		Vector3 ref0 = axlePtWorld - n0 * offset;
		Vector3 ref1 = holePtWorld + n1 * offset;

		if (Tolerance::pointsUnaligned(ref0, ref1)) {
			return NULL;
		}
	}

	return surfaceTypeToJoint(surfaceType0, p0, p1, axleInP0, holeInP1);
}

RotateJoint::getTorqueArmLength()
	{
		Primitive* axlePrim = getAxlePrim();
		Primitive* holePrim = getHolePrim();

		G3D::Vector3 ownerSize = axlePrim->getGridSize();
		G3D::Vector3 otherSize = holePrim->getGridSize();

		NormalId ownerId = getAxleId();
		NormalId otherId = normalIdOpposite(getHoleId());

		float ownerMax = G3D::max(ownerSize[(2 + (int)ownerId) % 3], ownerSize[(1 + (int)ownerId) % 3]);
		float otherMax = G3D::max(otherSize[(2 + (int)otherId) % 3], otherSize[(1 + (int)otherId) % 3]);
		float min = G3D::min(ownerMax, otherMax);

		return min * 0.1f;
	}

RotateJoint::getTorqueArmLength()
	{
	Vector3 ownerSize = getAxlePrim()->getGeometry()->getGridSize();
	Vector3 otherSize = getHolePrim()->getGeometry()->getGridSize();

	NormalId axleId = getAxleId();
	NormalId holeId = getHoleId();

	int holeIndex0 = (holeId + 1) % 3;
	int holeIndex1 = (holeId + 2) % 3;

	float ownerMax = std::max(ownerSize[(axleId + 1) % 3], ownerSize[(axleId + 2) % 3]);
	float otherMax = std::max(otherSize[holeIndex0], otherSize[holeIndex1]);

	return std::min(ownerMax, otherMax) * 0.1f;
}

RotateJoint::putInKernel(Kernel* _kernel)
	{
		MultiJoint::putInKernel(_kernel);

		Body* b0 = getAxlePrim()->getBody();
		Body* b1 = getHolePrim()->getBody();

		G3D::CoordinateFrame cAxleWorld = b0->getCoordinateFrame() * jointCoord0;
		G3D::CoordinateFrame cHoleWorld = b1->getCoordinateFrame() * jointCoord1;

		G3D::Vector3 vAxleWorld = cAxleWorld.rotation.getColumn(2);
		G3D::Vector3 vHoleWorld = cHoleWorld.rotation.getColumn(2);

		for (int i = 0; i < 2; i++)
		{
			float multiplier = i == 0 ? -1.0f : 1.0f;

			G3D::Vector3 pAxleWorldPos = vAxleWorld * multiplier + cAxleWorld.translation;
			G3D::Vector3 pHoleWorldPos = vHoleWorld * multiplier + cHoleWorld.translation;

			Point* pAxleWorld = getKernel()->newPoint(b0, pAxleWorldPos);
			Point* pHoleWorld = getKernel()->newPoint(b1, pHoleWorldPos);

			PointToPointBreakConnector* connector = new PointToPointBreakConnector(pAxleWorld, pHoleWorld, getJointK(), Math::inf());
			addToMultiJoint(pAxleWorld, pHoleWorld, connector);
		}

		if (getJointType() == ROTATE_P_JOINT || getJointType() == ROTATE_V_JOINT)
		{
			G3D::Vector3 center0 = cAxleWorld.translation;
			G3D::Vector3 perp = cAxleWorld.rotation.getColumn(0);
			G3D::Vector3 marker0 = perp * 10.0f + center0;

			Point* pMarker0 = getKernel()->newPoint(b0, marker0);
			Point* pMarker1 = getKernel()->newPoint(b1, marker0);

			RBXASSERT(!rotateConnector);
			RotateConnector* connector = new RotateConnector(getPoint(0), getPoint(2), pMarker0, pMarker1, getJointK(), getTorqueArmLength());
			rotateConnector = connector;
			addToMultiJoint(pMarker0, pMarker1, connector);
		}
	}

RotateJoint::putInKernel(Kernel* _kernel)
	{
	MultiJoint::putInKernel(_kernel);

	Body* b0 = getAxlePrim()->getBody();
	Body* b1 = getHolePrim()->getBody();

	CoordinateFrame cAxleWorld = b0->getCoordinateFrame() * jointCoord0;
	CoordinateFrame cHoleWorld = b1->getCoordinateFrame() * jointCoord1;

	Vector3 vAxleWorld = cAxleWorld.rotation.getColumn(2);
	Vector3 vHoleWorld = cHoleWorld.rotation.getColumn(2);

	for (int i = 0; i < 2; ++i) {
		float offset = i == 0 ? -1.0f : 1.0f;
		Vector3 pAxleWorld = cAxleWorld.translation + vAxleWorld * offset;
		Vector3 pHoleWorld = cHoleWorld.translation + vHoleWorld * offset;

		Point* point0 = getKernel()->newPoint(b0, pAxleWorld);
		Point* point1 = getKernel()->newPoint(b1, pHoleWorld);

		Connector* connector = new PointToPointBreakConnector(point0, point1, getJointK(), Math::inf());
		addToMultiJoint(point0, point1, connector);
	}

	if (getJointType() == ROTATE_P_JOINT || getJointType() == ROTATE_V_JOINT) {
		Vector3 center0 = cAxleWorld.translation;
		Vector3 perp = cAxleWorld.rotation.getColumn(0);
		Vector3 marker0 = center0 + perp * 10.0f;

		Point* point0 = getKernel()->newPoint(b0, marker0);
		Point* point1 = getKernel()->newPoint(b1, marker0);

		rotateConnector =
			new RotateConnector(getPoint(0), getPoint(2), point0, point1, getJointK(), getTorqueArmLength());

		addToMultiJoint(point0, point1, rotateConnector);
	}
}

RotateVJoint::stepUi(int uiStepId)
	{
		float value = getChannelValue(uiStepId);

		RotateConnector* connector = rotateConnector;
		if (connector)
		{
			float newValue = value / (float)Constants::kernelStepsPerUiStep();
			connector->getKernelInput()->setDelta(newValue);
		}

		if (value != 0.0f)
		{
			World* world = getWorld();
			world->ticklePrimitive(getAxlePrim());
			world->ticklePrimitive(getHolePrim());
		}
	}

RotateVJoint::stepUi(int uiStepId)
	{
	float value = getChannelValue(uiStepId);

	if (rotateConnector != NULL) {
		rotateConnector->getKernelInput().setDelta(value);
	}

	if (value != 0.0f) {
		World* world = getWorld();

		world->ticklePrimitive(getPrimitive(0), false);
		world->ticklePrimitive(getPrimitive(1), false);
	}
}

RotatePJoint::stepUi(int uiStepId)
	{
		float value = getChannelValue(uiStepId);

		RotateConnector* connector = rotateConnector;
		if (connector)
		{
			connector->getKernelInput()->setGoalCalc(value, calculateIncrementRotatePJoint);
		}

		if (value != 0.0f)
		{
			World* world = getWorld();
			world->ticklePrimitive(getAxlePrim());
			world->ticklePrimitive(getHolePrim());
		}
	}

RotatePJoint::stepUi(int uiStepId)
	{
	float value = getChannelValue(uiStepId);

	if (rotateConnector != NULL) {
		rotateConnector->getKernelInput().setGoal(value);
	}

	if (value != 0.0f) {
		World* world = getWorld();

		world->ticklePrimitive(getPrimitive(0), false);
		world->ticklePrimitive(getPrimitive(1), false);
	}
}

SimJobStage::onEdgeRemoving(Edge* e)
	{
		RBXASSERT(validateEdge(e));

		e->removeFromKernel();
		e->removeFromStage(this);
	}

SimJobStage::onEdgeRemoving(Edge* e)
