	e->removeFromKernel();

	e->removeFromStage(this);
}

SimJobStage::notifyMovingPrimitives()
	{
		std::for_each(this->mechanisms.begin(), this->mechanisms.end(), call_notifyMovingPrimitives);
	}

SimJobStage::notifyMovingPrimitives()
