	std::for_each(mechanisms.begin(), mechanisms.end(), std::mem_fun(&Mechanism::notifyMovingPrimitives));
}

SimJobStage::destroyMechanism(Mechanism* m)
	{
		RBXASSERT(std::find(this->mechanisms.begin(), this->mechanisms.end(), m) == m->myIt);
		Mechanism* next = this->mechanisms.size() > 1 ? this->nextMechanism(this->mechanisms, m) : NULL;
		MechanismTracker::transferTrackers(m, next);
		this->mechanisms.erase(m->myIt);
		delete m;
	}

SimJobStage::destroyMechanism(Mechanism* m)
	{
	Mechanism* next = mechanisms.size() > 1 ? nextMechanism(mechanisms, m) : NULL;

	MechanismTracker::transferTrackers(m, next);

	mechanisms.erase(m->myIt);

	delete m;
}

SimJobStage::onAssemblyAdded(Assembly* a)
	{
		a->putInStage(this);
		RBXASSERT(!a->getMechanism());
		Mechanism* newMech = new Mechanism;
		newMech->insertAssembly(a);
		this->insertMechanism(newMech);
		a->putInKernel(this->getKernel());
	}

SimJobStage::onAssemblyAdded(Assembly* a)
	{
	a->putInPipeline(this);

	Mechanism* mechanism = new Mechanism();
	mechanism->insertAssembly(a);

	insertMechanism(mechanism);

	a->putInKernel(getKernel());
}

SimJobStage::onAssemblyRemoving(Assembly* a)
	{
		a->removeFromKernel();
		Mechanism* mech = a->getMechanism();
		mech->removeAssembly(a);
		if (mech->getAssemblies().empty())
			this->destroyMechanism(mech);
		a->removeFromStage(this);
	}

SimJobStage::onAssemblyRemoving(Assembly* a)
	{
	a->removeFromKernel();

	Mechanism* mechanism = a->getMechanism();

	mechanism->removeAssembly(a);

	if (mechanism->getAssemblies().size() == 0) {
		destroyMechanism(mechanism);
	}

	a->removeFromStage(this);
}

SimJobStage::combineMechanisms(Edge* e)
	{
		RBXASSERT(e->getEdgeType() == Edge::JOINT);
		RBXASSERT(!RigidJoint::isRigidJoint(e));
		RBXASSERT(!MotorJoint::isMotorJoint(e));

		Joint* j = rbx_static_cast<Joint*>(e);
		Assembly* a0 = e->getPrimitive(0)->getAssembly();
		Assembly* a1 = e->getPrimitive(1)->getAssembly();
		RBXASSERT(a0->inOrDownstreamOfStage(this));
		RBXASSERT(a1->inOrDownstreamOfStage(this));

		Mechanism* m0 = a0->getMechanism();
		Mechanism* m1 = a1->getMechanism();
		if (m0 != m1)
		{
			Mechanism* m = (m0->getAssemblies().size() > m1->getAssemblies().size()) ? m0 : m1;
			Mechanism* other = (m == m1) ? m0 : m1;

			m->absorb(other);
			destroyMechanism(other);
		}
	}

SimJobStage::combineMechanisms(Edge* e)
	{
	Assembly* a0 = e->getPrimitive(0)->getAssembly();
	Assembly* a1 = e->getPrimitive(1)->getAssembly();

	Mechanism* m0 = a0->getMechanism();
	Mechanism* m1 = a1->getMechanism();

	if (m0 != m1) {
		Mechanism* bigger = m0->getAssemblies().size() > m1->getAssemblies().size() ? m0 : m1;
		Mechanism* smaller = bigger == m0 ? m1 : m0;

		bigger->absorb(smaller);

		destroyMechanism(smaller);
	}
}

SimJobStage::onEdgeAdded(Edge* e)
	{
		RBXASSERT(validateEdge(e));

		e->putInStage(this);

		if (e->getEdgeType() == Edge::JOINT)
		{
			Assembly* a0 = e->getPrimitive(0)->getAssembly();
			Assembly* a1 = e->getPrimitive(1)->getAssembly();

			if (a0->inOrDownstreamOfStage(this) && a1->inOrDownstreamOfStage(this))
			{
				RBXASSERT(a0->getDof() > 0);
				RBXASSERT(a1->getDof() > 0);

				combineMechanisms(e);
			}
		}

		e->putInKernel(getKernel());
	}

SimJobStage::onEdgeAdded(Edge* e)
	{
	e->putInPipeline(this);

	if (e->getEdgeType() == Edge::JOINT) {
		Assembly* a0 = e->getPrimitive(0)->getAssembly();
		Assembly* a1 = e->getPrimitive(1)->getAssembly();

		if (a0->inOrDownstreamOfStage(this) && a1->inOrDownstreamOfStage(this)) {
			combineMechanisms(e);
		}
	}

	e->putInKernel(getKernel());
}

SnapJoint::canBuildJoint(Primitive* p0, Primitive* p1, NormalId nId0, NormalId nId1)
	{
		if (!compatibleSurfaces(p0, p1, nId0, nId1) || !canBuildJointTight(p0, p1, nId0, nId1))
			return NULL;

		G3D::CoordinateFrame c0;
		G3D::CoordinateFrame c1;
		faceIdToCoords(p0, p1, nId0, nId1, c0, c1);

		return new SnapJoint(p0, p1, c0, c1);
	}

SnapJoint::canBuildJoint(Primitive* p0, Primitive* p1, NormalId nId0, NormalId nId1)
	{
	if (compatibleSurfaces(p0, p1, nId0, nId1) && canBuildJointTight(p0, p1, nId0, nId1)) {

		CoordinateFrame c0;
		CoordinateFrame c1;

		faceIdToCoords(p0, p1, nId0, nId1, c0, c1);

		return new SnapJoint(p0, p1, c0, c1);
	}

	return NULL;
}

SpatialHash::getHash(const Vector3int32& grid)
	{
		int result = grid.x * -0xba3 ^ grid.y * 0x409f ^ grid.z * -0x49;
		result &= (numBuckets()-1);
		RBXASSERT(result >= 0);
		RBXASSERT(result < (int)numBuckets());
		return result;
	}

SpatialHash::getHash(const Vector3int32& grid)
	{
	return (grid.x * -2979 ^ grid.y * 16543 ^ grid.z * -73) & (numBuckets() - 1);
}

SpatialHash::computeMinMax(const Extents& extents, Vector3int32& min, Vector3int32& max)
	{
		min = SpatialHash::realToHashGrid(extents.min());
		max = SpatialHash::realToHashGrid(extents.max());
	}

SpatialHash::computeMinMax(const Extents& extents, Vector3int32& min, Vector3int32& max)
	{
	min = realToHashGrid(extents.min());
	max = realToHashGrid(extents.max());
}

SpatialHash::removeNodeFromHash(SpatialNode* remove)
	{
		SpatialNode** temp = &this->nodes[remove->hashId];
		while (*temp != remove)
		{
			temp = &(*temp)->nextHashLink;
		}
		*temp = remove->nextHashLink;
	}

SpatialHash::removeNodeFromHash(SpatialNode* remove)
	{
	SpatialNode** link = &nodes[remove->hashId];

	while (*link != remove) {
		link = &(*link)->nextHashLink;
	}
	*link = remove->nextHashLink;
}

SpatialHash::findNode(Primitive* p, const Vector3int32& grid)
	{
		int hash = SpatialHash::getHash(grid);
		SpatialNode* result = this->nodes[hash];
		while (result->primitive != p || result->gridId != grid)
		{
			result = result->nextHashLink;
		}
		return result;
	}

SpatialHash::findNode(Primitive* p, const Vector3int32& grid)
	{
	int hash = getHash(grid);

	SpatialNode* node = nodes[hash];

	while (node->primitive != p || node->gridId != grid) {
		node = node->nextHashLink;
	}

	return node;
}

SpatialHash::destroyNode(SpatialNode* destroy)
	{
		SpatialNode* nextPrimitiveLink = destroy->nextPrimitiveLink;
		SpatialNode* prevPrimitiveLink = destroy->prevPrimitiveLink;

		if (nextPrimitiveLink)
			nextPrimitiveLink->prevPrimitiveLink = prevPrimitiveLink;

		if (prevPrimitiveLink)
			prevPrimitiveLink->nextPrimitiveLink = nextPrimitiveLink;
		else
			destroy->primitive->spatialNodes = nextPrimitiveLink;

		removeNodeFromHash(destroy);

		int destroyHash = destroy->hashId;
		Vector3int32 destroyGrid = destroy->gridId;

		for (SpatialNode* node = nodes[destroyHash]; node != NULL; node = node->nextHashLink)
		{
			if (node->gridId == destroyGrid)
			{
				Primitive* destroyPrim = destroy->primitive;
				Primitive* nodePrim = node->primitive;
				RBXASSERT(nodePrim != destroyPrim);
				if (Primitive::getContact(destroyPrim, nodePrim) && !shareCommonGrid(destroyPrim, nodePrim))
					this->contactManager->onReleasePair(destroyPrim, nodePrim);
			}
		}

		destroy->nextHashLink = this->extraNodes;
		--this->nodesOut;
		this->extraNodes = destroy;
	}

SpatialHash::destroyNode(SpatialNode* destroy)
	{
	removeNodeFromPrimitive(destroy);

	removeNodeFromHash(destroy);

	Vector3int32 destroyGrid = destroy->gridId;

	SpatialNode* node = nodes[destroy->hashId];

	while (node != NULL) {
		if (node->gridId == destroyGrid) {
			Primitive* me = destroy->primitive;
			Primitive* other = node->primitive;

			if (Primitive::getContact(me, other) != NULL) {
				if (!shareCommonGrid(me, other)) {
					contactManager->onReleasePair(me, other);
				}
			}
		}

		node = node->nextHashLink;
	}

	returnNode(destroy);
}

SpatialHash::shareCommonGrid(Primitive* me, Primitive* other)
	{
		SpatialNode* spatialNodes = me->spatialNodes;
		while (true)
		{
			if (!spatialNodes)
				return false;
			int hashId = spatialNodes->hashId;
			SpatialNode* currentNode = this->nodes[hashId];
			while (currentNode)
			{
				if (currentNode->primitive == other && currentNode->gridId == spatialNodes->gridId)
					return true;
				currentNode = currentNode->nextHashLink;
			}
			spatialNodes = spatialNodes->nextPrimitiveLink;
		}
	}

SpatialHash::shareCommonGrid(Primitive* me, Primitive* other)
	{
	for (SpatialNode* node = me->spatialNodes; node != NULL; node = node->nextPrimitiveLink) {
		for (SpatialNode* hashNode = nodes[node->hashId]; hashNode != NULL; hashNode = hashNode->nextHashLink) {
			if (hashNode->primitive == other && hashNode->gridId == node->gridId) {
				return true;
			}
		}
	}

	return false;
}

SpatialHash::addNode(Primitive* p, const Vector3int32& grid)
	{
		int hash = getHash(grid);

		SpatialNode* node = this->extraNodes;
		++this->nodesOut;
		if (node)
			this->extraNodes = node->nextHashLink;
		else
			node = new SpatialNode();

		node->primitive = p;
		node->gridId = grid;
		node->hashId = hash;

		SpatialNode* oldNodes = p->spatialNodes;
		p->spatialNodes = node;
		node->nextPrimitiveLink = oldNodes;
		node->prevPrimitiveLink = NULL;
		if (oldNodes)
			oldNodes->prevPrimitiveLink = node;

		SpatialNode* linkedNode = this->nodes[hash];
		node->nextHashLink = linkedNode;
		this->nodes[hash] = node;

		int numNodes = 1;
		while (linkedNode)
		{
			++numNodes;

			Primitive* linkedP = linkedNode->primitive;
			if (linkedP != p && linkedNode->gridId == grid)
			{
				if (!Primitive::getContact(p, linkedP))
					this->contactManager->onNewPair(p, linkedP);
			}
			else
			{
				RBXASSERT(grid != linkedNode->gridId);
			}

			linkedNode = linkedNode->nextHashLink;
		}

		this->maxBucket = std::max(this->maxBucket, numNodes);
	}

SpatialHash::addNode(Primitive* p, const Vector3int32& grid)
	{
	int hash = getHash(grid);

	SpatialNode* node = newNode();

	insertNodeToPrimitive(node, p, grid, hash);

	SpatialNode* other = nodes[hash];

	node->nextHashLink = other;
	nodes[hash] = node;

	int numNodes = 1;

	while (other != NULL) {
		Primitive* otherPrimitive = other->primitive;

		numNodes++;

		if (otherPrimitive != p && other->gridId == grid) {
			if (Primitive::getContact(p, otherPrimitive) == NULL) {
				contactManager->onNewPair(p, otherPrimitive);
			}
		}

		other = other->nextHashLink;
	}

	maxBucket = std::max(maxBucket, numNodes);
}

SpatialHash::changeMinMax(Primitive* p, const Extents& change, const Extents& oldBox, const Extents& newBox)
	{
		Vector3int32 min = Vector3int32::floor(change.min());
		Vector3int32 max = Vector3int32::floor(change.max());

		for (int i = min.x; i <= max.x; ++i)
		{
			for (int j = min.y; j <= max.y; ++j)
			{
				for (int k = min.z; k <= max.z; ++k)
				{
					bool inNew = newBox.contains(G3D::Vector3(i, j, k));
					bool inOld = oldBox.contains(G3D::Vector3(i, j, k));

					if (inNew)
					{
						if (!inOld)
							addNode(p, Vector3int32(i, j, k));
					}
					else if (inOld)
					{
						SpatialNode* node = findNode(p, Vector3int32(i, j, k));
						destroyNode(node);
					}
				}
			}
		}
	}

SpatialHash::changeMinMax(Primitive* p, const Extents& change, const Extents& oldBox, const Extents& newBox)
	{
	Vector3int32 min = Vector3int32::floor(change.min());
	Vector3int32 max = Vector3int32::floor(change.max());

	for (int i = min.x; i <= max.x; i++) {
		for (int j = min.y; j <= max.y; j++) {
			for (int k = min.z; k <= max.z; k++) {
				bool inNew = newBox.contains(Vector3((float) i, (float) j, (float) k));
				bool inOld = oldBox.contains(Vector3((float) i, (float) j, (float) k));

				if (inNew) {
					if (!inOld) {
						addNode(p, Vector3int32(i, j, k));
					}
				}
				else if (inOld) {
					SpatialNode* node = findNode(p, Vector3int32(i, j, k));

					destroyNode(node);
				}
			}
		}
	}
}

SpatialHash::primitiveExtentsChanged(Primitive* p)
	{
		RBXASSERT(p->spatialNodes);
		Vector3int32 newMin;
		Vector3int32 newMax;
		const Extents& fuzzyExtents = p->getFastFuzzyExtents();
		SpatialHash::computeMinMax(fuzzyExtents, newMin, newMax);
		if (newMin != p->oldSpatialMin || newMax != p->oldSpatialMax)
		{
			Extents newBox(newMin, newMax);
			Extents oldBox(p->oldSpatialMin, p->oldSpatialMax);
			if (newBox.overlapsOrTouches(oldBox))
			{
				Extents unionBox(newBox);
				unionBox.unionWith(oldBox);
				this->changeMinMax(p, unionBox, oldBox, newBox);
			}
			else
			{
				this->changeMinMax(p, oldBox, oldBox, newBox);
				this->changeMinMax(p, newBox, oldBox, newBox);
			}
			p->oldSpatialMin = newMin;
			p->oldSpatialMax = newMax;

		}
	}

SpatialHash::primitiveExtentsChanged(Primitive* p)
	{
	Vector3int32 newMin;
	Vector3int32 newMax;

	const Extents& extents = p->getFastFuzzyExtents();

	computeMinMax(extents, newMin, newMax);

	if (newMin != p->oldSpatialMin || newMax != p->oldSpatialMax) {
		Extents newBox(newMin, newMax);
		Extents oldBox(p->oldSpatialMin, p->oldSpatialMax);

		if (newBox.overlapsOrTouches(oldBox)) {
			Extents unionBox = newBox;
			unionBox.unionWith(oldBox);

			changeMinMax(p, unionBox, oldBox, newBox);
		}
		else {
			changeMinMax(p, oldBox, oldBox, newBox);
			changeMinMax(p, newBox, oldBox, newBox);
		}

		p->oldSpatialMin = newMin;
		p->oldSpatialMax = newMax;
	}
}

SpatialHash::onPrimitiveExtentsChanged(Primitive* p)
	{
		this->primitiveExtentsChanged(p);
	}

SpatialHash::onPrimitiveExtentsChanged(Primitive* p)
	{
	primitiveExtentsChanged(p);
}

SpatialHash::onPrimitiveAdded(Primitive* p)
	{
		RBXASSERT(!p->spatialNodes);
		Vector3int32 newMin;
		Vector3int32 newMax;
		const Extents& fuzzyExtents = p->getFastFuzzyExtents();
		SpatialHash::computeMinMax(fuzzyExtents, newMin, newMax);
		p->oldSpatialMin = newMin;
		p->oldSpatialMax = newMax;
		for (int i = newMin.x; i <= newMax.x; i++)
		{
			for (int j = newMin.y; j <= newMax.y; j++)
			{
				for (int k = newMin.z; k <= newMax.z; k++)
				{
					this->addNode(p, Vector3int32(i, j, k));
				}
			}
		}
	}

SpatialHash::onPrimitiveAdded(Primitive* p)
	{
	Vector3int32 newMin;
	Vector3int32 newMax;

	const Extents& extents = p->getFastFuzzyExtents();

	computeMinMax(extents, newMin, newMax);

	p->oldSpatialMin = newMin;
	p->oldSpatialMax = newMax;

	for (int i = newMin.x; i <= newMax.x; i++) {
		for (int j = newMin.y; j <= newMax.y; j++) {
			for (int k = newMin.z; k <= newMax.z; k++) {
				addNode(p, Vector3int32(i, j, k));
			}
		}
	}
}

SpatialHash::onPrimitiveRemoved(Primitive* p)
	{
		for (SpatialNode* node = p->spatialNodes; node != NULL; node = p->spatialNodes)
			destroyNode(node);
	}

SpatialHash::onPrimitiveRemoved(Primitive* p)
	{
	while (p->spatialNodes != NULL) {
		destroyNode(p->spatialNodes);
	}
}

SpatialHash::onAllPrimitivesMoved()
	{
		const G3D::Array<Primitive*>& primitives = this->world->getPrimitives();
		for (int i = 0; i < primitives.size(); i++)
		{
			Primitive* primitive = primitives[i];
			RBXASSERT(primitive);
			RBXASSERT(primitive->getClump());
			if (primitive->getAssembly()->moving())
				this->primitiveExtentsChanged(primitive);
		}
	}

SpatialHash::onAllPrimitivesMoved()
	{
	const G3D::Array<Primitive*>& primitives = world->getPrimitives();

	for (int i = 0; i < primitives.size(); i++) {
		Primitive* p = primitives[i];

		Assembly* a = p->getAssembly();

		if (a->getSleepStatus() == Sim::AWAKE) {
			primitiveExtentsChanged(p);
		}
	}
}

SpatialHash::getPrimitivesInGrid(const Vector3int32& grid, G3D::Array<Primitive*>& found)
	{
		RBXASSERT(found.size() == 0);
		int hash = SpatialHash::getHash(grid);
		SpatialNode* node = this->nodes[hash];
		while (node)
		{
			if (node->gridId == grid)
				found.append(node->primitive);

			node = node->nextHashLink;
		}
	}

SpatialHash::getPrimitivesInGrid(const Vector3int32& grid, G3D::Array<Primitive*>& found)
	{
	int hash = getHash(grid);

	SpatialNode* node = nodes[hash];

	while (node != NULL) {
		if (node->gridId == grid) {
			found.append(node->primitive);
		}

		node = node->nextHashLink;
	}
}

SpatialHash::getPrimitivesTouchingExtents(const Extents& extents, const Primitive* ignore, G3D::Array<Primitive*>& answer)
	{
		RBXASSERT(answer.size() == 0);
		Vector3int32 min;
		Vector3int32 max;
		SpatialHash::computeMinMax(extents, min, max);
		G3D::Array<Primitive*> foundThisGrid;

		for (int i = min.x; i <= max.x; i++)
		{
			for (int j = min.y; j <= max.y; j++)
			{
				for (int k = min.z; k <= max.z; k++)
				{
					foundThisGrid.fastClear();
					this->getPrimitivesInGrid(Vector3int32(i, j, k), foundThisGrid);
					for (int l = 0; l < foundThisGrid.size(); l++)
					{
						Primitive* primitive = foundThisGrid[l];
						if (primitive != ignore && !answer.contains(primitive))
						{
							if (extents.overlapsOrTouches(primitive->getFastFuzzyExtents()))
								answer.append(primitive);
						}
					}
				}
			}
		}
		RBXASSERT(foundThisGrid.size() < 200);
	}

SpatialHash::getPrimitivesTouchingExtents(const Extents& extents, const Primitive* ignore, G3D::Array<Primitive*>& answer)
	{
	Vector3int32 min;
	Vector3int32 max;

	computeMinMax(extents, min, max);

	G3D::Array<Primitive*> foundThisGrid;

	for (int i = min.x; i <= max.x; i++) {
		for (int j = min.y; j <= max.y; j++) {
			for (int k = min.z; k <= max.z; k++) {
				foundThisGrid.resize(0, false);

				getPrimitivesInGrid(Vector3int32(i, j, k), foundThisGrid);

				for (int index = 0; index < foundThisGrid.size(); index++) {
					Primitive* p = foundThisGrid[index];

					if (p != ignore && !answer.contains(p) && extents.overlapsOrTouches(p->getFastFuzzyExtents())) {
						answer.append(p);
					}
				}
			}
		}
	}
}

SpatialHash::getNextGrid(Vector3int32& grid, const G3D::Ray& unitRay, float maxDistance)
	{
		Vector3int32 min;
		Vector3int32 max;

		for (int i = 0; i < 3; i++)
		{
			min[i] = unitRay.direction[i] < 0.0f ? -1 : 0;
			max[i] = unitRay.direction[i] > 0.0f ? 1 : 0;
		}

		G3D::Vector3 gridF = grid.toVector3();
		float distanceSquared = G3D::square(maxDistance + 16.0f);

		for (int idfk = 1; idfk <= 3; idfk++)
		{
			for (int i = min.x; i <= max.x; i++)
			{
				for (int j = min.y; j <= max.y; j++)
				{
					for (int k = min.z; k <= max.z; k++)
					{
						if (abs(i)+abs(j)+abs(k) == idfk)
						{
							G3D::Vector3 offset(i, j, k);
							G3D::Vector3 offsetGridF = (offset + gridF);
							G3D::AABox box(offsetGridF * 8.0f, (offsetGridF + G3D::Vector3(1,1,1)) * 8.0f);
							G3D::Vector3 location;

							bool hit = G3D::CollisionDetection::collisionLocationForMovingPointFixedAABox(
								unitRay.origin,
								unitRay.direction,
								box,
								location);

							if (hit && (location - unitRay.origin).squaredMagnitude() < distanceSquared)
							{
									grid = Vector3int32::floor(offset + gridF);
									return true;
							}
						}
					}
				}
			}
		}
		return false;
	}

SpatialHash::getNextGrid(Vector3int32& grid, const G3D::Ray& unitRay, float maxDistance)
	{
	Vector3int32 low;
	Vector3int32 high;

	for (int a = 0; a < 3; a++) {
		low[a] = unitRay.direction[a] < 0.0f ? -1 : 0;
		high[a] = unitRay.direction[a] > 0.0f ? 1 : 0;
	}

	Vector3 gridF = grid.toVector3();

	float maxCheck = maxDistance + 2.0f * hashGridSize();

	float maxDistanceSquared = maxCheck * maxCheck;

	for (int nz = 1; nz <= 3; nz++) {
		for (int i = low.x; i <= high.x; i++) {
			for (int j = low.y; j <= high.y; j++) {
				for (int k = low.z; k <= high.z; k++) {
					if (abs(i) + abs(j) + abs(k) == nz) {
						Vector3 offset((float) i, (float) j, (float) k);

						Extents box = hashGridToRealExtents(gridF + offset);

						G3D::AABox aaBox(box.min(), box.max());

						Vector3 location;

						if (G3D::CollisionDetection::collisionLocationForMovingPointFixedAABox(
								unitRay.origin,
								unitRay.direction,
								aaBox,
								location
							)) {
							if ((location - unitRay.origin).squaredLength() < maxDistanceSquared) {
								grid = Vector3int32::floor(gridF + offset);

								return true;
							}
						}
					}
				}
			}
		}
	}

	return false;
}

WeldJoint::canBuildJoint(Primitive* p0, Primitive* p1, NormalId nId0, NormalId nId1)
	{
		if (!compatibleSurfaces(p0, p1, nId0, nId1) || !canBuildJointTight(p0, p1, nId0, nId1))
			return NULL;

		G3D::CoordinateFrame c0;
		G3D::CoordinateFrame c1;
		faceIdToCoords(p0, p1, nId0, nId1, c0, c1);

		return new WeldJoint(p0, p1, c0, c1);
	}

WeldJoint::canBuildJoint(Primitive* p0, Primitive* p1, NormalId nId0, NormalId nId1)
	{
	if (compatibleSurfaces(p0, p1, nId0, nId1) && canBuildJointTight(p0, p1, nId0, nId1)) {

		CoordinateFrame c0;
		CoordinateFrame c1;

		faceIdToCoords(p0, p1, nId0, nId1, c0, c1);

		return new WeldJoint(p0, p1, c0, c1);
	}

	return NULL;
}

