World::computeFallen(G3D::Array<Primitive*>& fallen) const
	{
		typedef std::set<Assembly*>::const_iterator Iter; 

		RBXASSERT(fallen.size() == 0);

		const SleepStage* sStage = rbx_static_cast<SleepStage*>(jointStage->findStage(IStage::SLEEP_STAGE)); // World::getSleepStage()

		for (Iter cIt = sStage->getAwakeAssemblies().begin(); cIt != sStage->getAwakeAssemblies().end(); cIt++)
		{
			const Assembly* current = *cIt;
			if (current->getMainPrimitive()->getCoordinateFrame().translation.y < -500.0f)
			{
				Assembly::PrimIterator it = Assembly::PrimIterator::begin(current);
				Assembly::PrimIterator pEnd = Assembly::PrimIterator::end(current);
				for (; it != pEnd; ++it)
				{
					Primitive* currentPrim = *it;
					if (currentPrim->getCoordinateFrame().translation.y < -500.0f)
						fallen.push_back(currentPrim);
				}
			}
		}
	}

World::computeFallen(G3D::Array<Primitive*>& fallen) const
	{
	const SleepStage::AssemblySet& awake = getSleepStage()->getAwakeAssemblies();

	for (SleepStage::CAssemblySetIt cIt = awake.begin(); cIt != awake.end(); cIt++) {

		Assembly* assembly = *cIt;

		if (assembly->getAssemblyPrimitive()->getCoordinateFrame().translation.y < -500.0f) {

			PrimIterator pEnd = assembly->assemblyPrimEnd();

			for (PrimIterator it = assembly->assemblyPrimBegin(); it != pEnd; ++it) {

				Primitive* p = *it;

				if (p->getCoordinateFrame().translation.y < -500.0f) {
					fallen.append(p);
				}
			}
		}
	}
}

World::step(float desiredInterval)
	{
		assertNotInStep();

		Profiling::Mark mark(*profilingWorldStep, true);

		RBXASSERT(desiredInterval > 0.01);
		RBXASSERT(desiredInterval < 0.1);

		update();

		double startTick = G3D::System::getTick();
		bool throttling = false;
		int startTime = G3D::max(1, Math::iRound(floorf(desiredInterval * Constants::worldStepsPerSec())));

		for (int i = 0; i < startTime; i++)
		{
			int numOfSteps = worldStepId / Constants::worldStepsPerUiStep();

			if (worldStepId % Constants::worldStepsPerUiStep() == 0)
			{
				Profiling::Mark markUI(*profilingUiStep, false);
				doBreakJoints();
				touch.fastClear();
				touchOther.fastClear();

				inStepCode = true;
				getClumpStage()->stepUi(numOfSteps);
				getSimJobStage().notifyMovingPrimitives();
				inStepCode = false;
			}

			{
				inStepCode = true;
				Profiling::Mark markBroadphase(*profilingBroadphase, false);
				contactManager->stepWorld();
				inStepCode = false;
			}

			inStepCode = true;
			jointStage->stepWorld(worldStepId, numOfSteps, throttling);
			inStepCode = false;

			if (!World::disableEnvironmentalThrottle && canThrottle)
				throttling = G3D::System::getTick() > (i + 1) * Constants::worldDt() + startTick;
			else
				throttling = false;

			worldStepId++;
		}

		return Constants::worldDt() * startTime;
	}

World::step(float desiredInterval)
	{
	Profiling::Mark mark(*profilingWorldStep, true);

	update();

	double startTime = G3D::System::getTick();

	bool throttling = false;

	int steps = std::max(1, G3D::iRound((float) floor(Constants::worldStepsPerSec() * desiredInterval)));

	for (int j = 0; j < steps; j++) {

		int uiStepId = worldStepId / Constants::worldStepsPerUiStep();

		if (worldStepId % Constants::worldStepsPerUiStep() == 0) {

			Profiling::Mark mark(*profilingUiStep, false);

			doBreakJoints();

			touch.resize(0, false);
			touchOther.resize(0, false);

			inStepCode = true;

			getClumpStage()->stepUi(uiStepId);

			getSimJobStage().notifyMovingPrimitives();

			inStepCode = false;
		}

		{
			inStepCode = true;

			Profiling::Mark mark(*profilingBroadphase, false);

			contactManager->stepWorld();

			inStepCode = false;
		}

		inStepCode = true;

		jointStage->stepWorld(worldStepId, uiStepId, throttling);

		inStepCode = false;

		throttling = !disableEnvironmentalThrottle && canThrottle &&
					 G3D::System::getTick() > startTime + Constants::worldDt() * (j + 1);

		worldStepId++;
	}

	return Constants::worldDt() * steps;
}

World::insertJoint(Joint* j)
	{
		assertNotInStep();
		RBXASSERT(!inJointNotification);

		if (j->getPrimitive(0) && j->getPrimitive(1))
		{
			Joint* d = Primitive::getJoint(j->getPrimitive(0), j->getPrimitive(1));
			if (d)
			{
				inJointNotification = true;
				Notifier<World, AutoDestroy>::raise(AutoDestroy(d));
				inJointNotification = false;
			}
		}

		jointStage->onEdgeAdded(j);
		numJoints++;

		if (j->isBreakable())
		{
			size_t success = breakableJoints.insert(j).second; 
			RBXASSERT(success);
		}
	}

World::insertJoint(Joint* j)
	{
	Primitive* p0 = j->getPrimitive(0);
	Primitive* p1 = j->getPrimitive(1);

	if (p0 != NULL && p1 != NULL) {
		Joint* existing = Primitive::getJoint(p0, p1);

		if (existing != NULL) {
			destroyJoint(existing);
		}
	}

	jointStage->onEdgeAdded(j);

	numJoints++;

	if (j->isBreakable()) {
		breakableJoints.insert(j);
	}
}

World::doBreakJoints()
	{
		std::set<Joint*>::iterator cIt = this->breakableJoints.begin();

		while (cIt != this->breakableJoints.end())
		{
			Joint* currentJoint = *cIt;
			cIt++;

			if (currentJoint->inKernel() && currentJoint->isBroken())
			{
				this->inJointNotification = true;
				Notifier<World, AutoDestroy>::raise(AutoDestroy(currentJoint));
				this->inJointNotification = false;
			}
		}
	}

World::doBreakJoints()
	{
	std::set<Joint*>::iterator it = breakableJoints.begin();

	while (it != breakableJoints.end()) {

		Joint* joint = *it;
		++it;

		if (joint->inKernel() && joint->isBroken()) {
			destroyJoint(joint);
		}
	}
}

ArchiveBinder::resolveRefs()
{
	size_t counts = std::count_if(idrefBindings.begin(), idrefBindings.end(), boost::bind(&ArchiveBinder::resolveIDREF, this, _1));

	return MergeBinder::resolveRefs() && counts == idrefBindings.size();
}

ArchiveBinder::resolveRefs()
{
	size_t resolvedCount = std::count_if(
		idrefBindings.begin(),
		idrefBindings.end(),
		std::bind1st(std::mem_fun(&ArchiveBinder::resolveIDREF), this)
	);

	return MergeBinder::resolveRefs() && resolvedCount == idrefBindings.size();
}

ArchiveBinder::resolveIDREF(IDREFBinding binding)
{
	std::string s;
	bool success = binding.valueIDREF->getValue(s);

	RBXASSERT(success);
	RBXASSERT(value_IDREF_nil.name.compare(s));
	RBXASSERT(value_IDREF_null.name.compare(s));
	RBXASSERT(s != "");

	std::map<std::string, RBX::InstanceHandle>::iterator found = idMap.find(s);
	if (found != idMap.end())
	{
		RBX::InstanceHandle& foundHandle = found->second;
		binding.idref->assignIDREF(binding.propertyOwner,foundHandle);
		return true;
	}
	else
	{
		binding.idref->assignIDREF(binding.propertyOwner,RBX::InstanceHandle(NULL));
		return false;
	}
}

ArchiveBinder::resolveIDREF(IDREFBinding binding)
{
	std::string s;
	binding.valueIDREF->getValue(s);

	std::map<std::string, RBX::InstanceHandle>::iterator iter = idMap.find(s);

	if (iter != idMap.end()) {
		const RBX::InstanceHandle& value = iter->second;

		binding.idref->assignIDREF(binding.propertyOwner, value);

		return true;
	}

	binding.idref->assignIDREF(binding.propertyOwner, RBX::InstanceHandle(NULL));

	return false;
}

ArchiveBinder::processID(const XmlNameValuePair* valueID, RBX::Instance* source)
{
	if (!MergeBinder::processID(valueID, source))
	{
		std::string s;
		bool success = valueID->getValue(s);

		RBXASSERT(success);
		RBXASSERT(idMap.find(s) == idMap.end());

		idMap[s] = shared_from(source);
	}

	return true;
}

ArchiveBinder::processID(const XmlNameValuePair* valueID, RBX::Instance* source)
{
	if (!MergeBinder::processID(valueID, source)) {
		std::string s;
		valueID->getValue(s);

		idMap[s].linkTo(RBX::shared_from(source));
	}

	return true;
}

