XmlNameValuePair::isValueEqual(const RBX::Name* value) const
{
	switch (valueType)
	{
	case NAME:
		return value == nameValue;
	case STRING:
		return *value == *stringValue;
	default:
		return false;
	}
}

XmlNameValuePair::isValueEqual(const RBX::Name* value) const
{
	switch (valueType) {
	case STRING: {
		const std::string& text = *stringValue;

		return value->name.compare(text) == 0;
	}
	case NAME:
		return value == nameValue;
	default:
		return false;
	}
}

XmlElement::findFirstChildByTag(const RBX::Name& _tag) const
{
	const XmlElement* child;
	for (child = firstChild(); child != NULL; child = child->nextSibling())
	{
		if (child->getTag() == _tag)
			return child;
	}

	return NULL;
}

XmlElement::findFirstChildByTag(const RBX::Name& _tag) const
{
	for (const XmlElement* child = firstChild(); child != NULL; child = child->nextSibling()) {
		if (&child->getTag() == &_tag) {
			return child;
		}
	}

	return NULL;
}

XmlElement::findNextChildWithSameTag(const XmlElement* node) const
{
	const XmlElement* child;
	for (child = node->nextSibling(); child != NULL; child = child->nextSibling())
	{
		if (child->getTag() == node->getTag())
			return child;
	}

	return NULL;
}

XmlElement::findNextChildWithSameTag(const XmlElement* node) const
{
	for (const XmlElement* next = node->nextSibling(); next != NULL; next = next->nextSibling()) {
		if (&next->getTag() == &node->getTag()) {
			return next;
		}
	}

	return NULL;
}

