TextXmlWriter::writeOpenTag(const XmlElement* element, int depth, const XmlAttribute* extraAttribute)
{
	for (int i = 0; i < depth; i++)
		stream << '\t';

	stream << '<' << element->getTag().name;

	for (const XmlAttribute* attribute = element->getFirstAttribute(); attribute != NULL; attribute = attribute->nextSibling())
	{
		stream << ' ' << attribute->getTag().name << "=\"";
		encodedWrite(stream, attribute->toString(this));
		stream << '\"';
	}

	if (extraAttribute)
	{
		stream << ' ' << extraAttribute->getTag().name << "=\"";
		encodedWrite(stream, extraAttribute->toString(this));
		stream << '\"';
	}

	stream << '>';
}

TextXmlWriter::writeOpenTag(const XmlElement* element, int depth, const XmlAttribute* extraAttribute)
{
	for (int i = 0; i < depth; ++i) {
		stream << '\t';
	}

	stream << '<' << element->getTag().name;

	for (const XmlAttribute* attribute = element->getFirstAttribute(); attribute != NULL;
		 attribute = element->getNextAttribute(attribute)) {
		stream << ' ' << attribute->getTag().name << "=\"";

		encodedWrite(stream, attribute->toString(this));

		stream << '"';
	}

	if (extraAttribute != NULL) {
		stream << ' ' << extraAttribute->getTag().name << "=\"";

		encodedWrite(stream, extraAttribute->toString(this));

		stream << '"';
	}

	stream << '>';
}

TextXmlWriter::writeCloseTag(const XmlElement* element, int depth)
{
	for (int i = 0; i < depth; i++)
		stream << '\t';

	stream << "</" << element->getTag().name << '>';
}

TextXmlWriter::writeCloseTag(const XmlElement* element, int depth)
{
	for (int i = 0; i < depth; ++i) {
		stream << '\t';
	}

	stream << "</" << element->getTag().name << '>';
}

TextXmlWriterWithEmbeddedContent::serializeNode(const XmlElement* xmlNode, int depth)
{
	if (xmlNode->isValueType<RBX::ContentId>())
	{
		RBX::ContentId contentId;
		xmlNode->getValue(contentId);

		if (contentId.mimeType() == RBX::Name::getNullName())
		{
			writeOpenTag(xmlNode, depth, NULL);
		}
		else
		{
			XmlAttribute mimeTypeAttribute(tag_mimeType, contentId.mimeType().c_str());
			writeOpenTag(xmlNode, depth, &mimeTypeAttribute);
		}

		if (!xmlNode->findAttribute(name_xsinil))
		{
			if (contentId.isNull())
			{
				stream << "<null></null>";
			}
			else
			{
				if (contentId.isAsset() || contentId.isHttp())
				{
					stream << "<url>";
					TextXmlWriter::encodedWrite(stream, contentId.toString());
					stream << "</url>";
				}
				else if (embeddedContent.find(contentId) == embeddedContent.end())
				{
					embeddedContent.insert(contentId);

					std::auto_ptr<std::istream> contentStream;

					try
					{
						contentStream = RBX::ContentProvider::singleton().getContent(contentId);

						if (contentId.mimeType() == RBX::Name::getNullName())
						{
							stream << "<binary>";
						}
						else
						{
							stream << "<binary xmime:contentType=\"" << contentId.mimeType().c_str() << "\">";
						}

						std::istreambuf_iterator<char> _From(contentStream->rdbuf());
						std::istreambuf_iterator<char> _To;
						std::ostreambuf_iterator<char> _Out(stream.rdbuf());
						int _State;

						base64<char> encoder;
						encoder.put(_From, _To, _Out, _State, base64<>::crlf());

						stream << "</binary>";
					}
					catch (std::exception&)
					{
						goto hash;
					}
				}
				else
				{
hash:
					embeddedContent.insert(contentId);

					stream << "<hash>";
					stream << xmlNode->toString(this);
					stream << "</hash>";
				}
			}
		}
	}
	else
	{
		TextXmlWriter::serializeNode(xmlNode, depth);
	}
}

TextXmlWriterWithEmbeddedContent::serializeNode(const XmlElement* xmlNode, int depth)
{
	if (xmlNode->isValueType<RBX::ContentId>()) {
		RBX::ContentId contentId;

		xmlNode->getValue(contentId);

		if (&contentId.mimeType() == &RBX::Name::getNullName()) {
			writeOpenTag(xmlNode, depth, NULL);
		}
		else {
			XmlAttribute mimeType(tag_mimeType, contentId.mimeType().name.c_str());

			writeOpenTag(xmlNode, depth, &mimeType);
		}

		if (xmlNode->findAttribute(name_xsinil) == NULL) {
			if (contentId.isNull()) {
				stream << "<null></null>";
			}
			else if (contentId.isAsset() || contentId.isHttp()) {
				stream << "<url>";
				TextXmlWriter::encodedWrite(stream, contentId.c_str());
				stream << "</url>";
			}
			else if (embeddedContent.find(contentId) == embeddedContent.end()) {
				embeddedContent.insert(contentId);

				std::auto_ptr<std::istream> contentStream;

				contentStream = RBX::ContentProvider::singleton().getContent(contentId);

				if (&contentId.mimeType() == &RBX::Name::getNullName()) {
					stream << "<binary>";
				}
				else {
					stream << "<binary xmime:contentType=\"" << contentId.mimeType().name.c_str() << "\">";
				}

				int state;
				base64<char> encoder;

				encoder.put(
					std::istreambuf_iterator<char>(contentStream->rdbuf()),
					std::istreambuf_iterator<char>(),
					std::ostreambuf_iterator<char>(stream.rdbuf()),
					state,
					base64<char>::crlf()
				);

				stream << "</binary>";
			}
			else {
				embeddedContent.insert(contentId);

				stream << "<hash>";
				stream << xmlNode->toString(this);
				stream << "</hash>";
			}
		}
	}
	else {
		TextXmlWriter::serializeNode(xmlNode, depth);
	}
}
